"use client";
import { cn } from "@/lib/utils";

import { useRef, useState, type ReactNode } from "react";
import { ArrowUpRight } from "lucide-react";
import { Button } from "@/components/ui/button";

export function MagneticButton({
  className,
  children = "Pull me",
  onClick,
}: {
  className?: string;
  children?: ReactNode;
  onClick?: () => void;
}) {
  const follower = useRef<HTMLDivElement>(null);
  function move(x: number, y: number) {
    const node = follower.current;
    if (!node) return;
    node.style.transform = "translate(" + x + "px," + y + "px)";
    node.style.setProperty("--ink-x", x * 0.22 + "px");
    node.style.setProperty("--ink-y", y * 0.22 + "px");
  }
  const [pulse, setPulse] = useState(0);

  return (
    <div
      className="relative inline-grid place-items-center p-4"
      onPointerMove={(event) => {
        if (event.pointerType === "touch") return;
        const rect = event.currentTarget.getBoundingClientRect();
        move(
          (event.clientX - rect.left - rect.width / 2) * 0.32,
          (event.clientY - rect.top - rect.height / 2) * 0.32,
        );
      }}
      onPointerLeave={() => {
        move(0, 0);
      }}
    >
      <div
        ref={follower}
        className="relative transition-transform duration-300 ease-[cubic-bezier(.22,1,.36,1)] motion-reduce:transform-none! motion-reduce:transition-none"
      >
        {pulse > 0 && (
          <span
            key={pulse}
            aria-hidden
            className="pointer-events-none absolute inset-0 rounded-full border border-primary/60 opacity-0 motion-safe:animate-ping [animation-iteration-count:1]"
          />
        )}
        <Button
          type="button"
          onClick={() => {
            setPulse((p) => p + 1);
            onClick?.();
          }}
          className={cn(
            "group h-13 cursor-pointer gap-4 rounded-full border border-white/15 bg-[linear-gradient(160deg,#44504b,#181f1c_80%)] pr-2 pl-6 text-sm font-medium text-white shadow-[inset_0_1px_1px_#ffffff44,0_4px_6px_-3px_#151a1866,0_14px_20px_-12px_#13191688] motion-safe:active:scale-[.96]",
            className,
          )}
        >
          <span className="motion-safe:translate-x-(--ink-x) motion-safe:translate-y-(--ink-y) motion-safe:transition-transform">
            {children}
          </span>
          <span className="grid size-9 place-items-center rounded-full border border-white/15 bg-white/10">
            <ArrowUpRight
              aria-hidden
              className="size-4 motion-safe:transition-transform motion-safe:group-hover:translate-x-0.5 motion-safe:group-hover:-translate-y-0.5"
            />
          </span>
        </Button>
      </div>
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useEffect, useRef, useState } from "react";
import { Minus, Plus } from "lucide-react";

function Digit({
  value,
  previous,
  direction,
}: {
  value: string;
  previous: string;
  direction: number;
}) {
  const flap = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const el = flap.current;
    if (
      !el ||
      previous === value ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    )
      return;
    const anim = el.animate(
      [
        { transform: "rotateX(0deg)", opacity: 1 },
        { transform: "rotateX(" + -direction * 88 + "deg)", opacity: 0.55 },
      ],
      { duration: 190, easing: "cubic-bezier(.32,0,.8,.5)", fill: "none" },
    );
    return () => anim.cancel();
  }, [previous, value, direction]);
  return (
    <span className="relative grid h-[58px] w-[43px] place-items-center overflow-hidden rounded-[7px] border border-[#4c4e53] bg-[linear-gradient(#3b3d42_0%,#282a2e_49%,#202226_50%,#303237_100%)] font-mono text-[40px] leading-none font-medium text-white shadow-[inset_0_1px_0_#ffffff28,0_2px_3px_#0003] [perspective:180px]">
      {value}
      <span
        ref={flap}
        className={
          "pointer-events-none absolute inset-x-0 h-1/2 overflow-hidden bg-[#36383c] opacity-0 " +
          (direction > 0 ? "top-0 origin-bottom" : "bottom-0 origin-top")
        }
      >
        <i
          className={
            "absolute inset-x-0 grid h-[62px] place-items-center not-italic " +
            (direction > 0 ? "top-0" : "bottom-0")
          }
        >
          {previous}
        </i>
      </span>
      <i className="absolute inset-x-0 top-1/2 h-px bg-black/60 shadow-[0_1px_0_#ffffff16]" />
    </span>
  );
}
export function FlipCounter({
  className,
  defaultValue = 12,
  min = 0,
  max = 99,
  onValueChange,
}: {
  className?: string;
  defaultValue?: number;
  min?: number;
  max?: number;
  onValueChange?: (value: number) => void;
}) {
  const [count, setCount] = useState(() =>
    Math.min(max, Math.max(min, defaultValue)),
  );
  const [before, setBefore] = useState(count);
  function step(delta: number) {
    const next = Math.min(max, Math.max(min, count + delta));
    if (next === count) return;
    setBefore(count);
    setCount(next);
    onValueChange?.(next);
  }
  const digits =
    (count < 0 ? "−" : "") + String(Math.abs(count)).padStart(2, "0");
  const old =
    (before < 0 ? "−" : "") + String(Math.abs(before)).padStart(2, "0");
  const control =
    "grid size-9 cursor-pointer place-items-center rounded-full border border-foreground/10 bg-card text-card-foreground shadow-sm motion-safe:transition-transform motion-safe:active:scale-90 disabled:opacity-35";
  return (
    <div
      role="group"
      aria-label="Counter"
      onKeyDown={(e) => {
        if (e.key === "ArrowUp" || e.key === "ArrowDown") {
          e.preventDefault();
          step(e.key === "ArrowUp" ? 1 : -1);
        }
      }}
      className={cn("flex items-center gap-3", className)}
    >
      <button
        type="button"
        className={control}
        aria-label="Decrease"
        disabled={count <= min}
        onClick={() => step(-1)}
      >
        <Minus size={16} />
      </button>
      <output aria-live="polite">
        <span className="sr-only">{count}</span>
        <span
          aria-hidden
          className="flex gap-[3px] rounded-xl border border-black/30 bg-[#191a1d] p-[4px] shadow-[0_9px_16px_-8px_#0007]"
        >
          {Array.from(digits).map((digit, i) => (
            <Digit
              key={digits.length - i}
              value={digit}
              previous={old[old.length - digits.length + i] ?? digit}
              direction={count >= before ? 1 : -1}
            />
          ))}
        </span>
      </output>
      <button
        type="button"
        className={control}
        aria-label="Increase"
        disabled={count >= max}
        onClick={() => step(1)}
      >
        <Plus size={16} />
      </button>
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { orbitCover } from "@/lib/takt-art-orbit";
import { foldCover } from "@/lib/takt-art-fold";
import { glassCover } from "@/lib/takt-art-glass";

export type DeckCard = {
  title: string;
  color: string;
  ink: string;
  cover?: string;
};
const posters: DeckCard[] = [
  { title: "Orbit", color: "#b0c2ba", ink: "#1f2824", cover: orbitCover },
  { title: "Fold", color: "#a6bdd4", ink: "#15263c", cover: foldCover },
  { title: "Glass", color: "#acd0c4", ink: "#15362c", cover: glassCover },
];
export function SwipeDeck({
  className,
  cards = posters,
  onSwipe,
}: {
  className?: string;
  cards?: DeckCard[];
  onSwipe?: (card: DeckCard, direction: "left" | "right") => void;
}) {
  const [index, setIndex] = useState(0);
  const lead = useRef<HTMLSpanElement>(null);
  const drag = useRef<{
    id: number;
    x: number;
    y: number;
    lastX: number;
    time: number;
    speed: number;
    tilt: number;
    width: number;
    travelled: boolean;
  } | null>(null);
  const suppressClick = useRef(false);
  const leaving = useRef(false);
  if (!cards.length) return null;
  const front = index % cards.length;
  const reduce = () =>
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  async function turn(direction: number) {
    if (leaving.current || cards.length < 2) return;
    leaving.current = true;
    const node = lead.current;
    if (node && !reduce()) {
      const exit = node.animate(
        [
          { transform: getComputedStyle(node).transform, opacity: 1 },
          {
            transform:
              "translateX(" +
              direction * 68 +
              "px) rotate(" +
              direction * 18 +
              "deg) scale(.95)",
            opacity: 0,
          },
        ],
        { duration: 240, easing: "cubic-bezier(.4,0,.8,.4)" },
      );
      try {
        await exit.finished;
      } catch {
        return;
      } finally {
        leaving.current = false;
      }
    }
    onSwipe?.(cards[front], direction < 0 ? "left" : "right");
    node?.style.removeProperty("--next");
    node?.style.removeProperty("--previous");
    setIndex((i) => (i - direction + cards.length) % cards.length);
    leaving.current = false;
  }
  function releaseCard() {
    drag.current = null;
    if (!lead.current) return;
    lead.current.style.removeProperty("transition");
    lead.current.style.removeProperty("--next");
    lead.current.style.removeProperty("--previous");
    lead.current.style.transform = "rotate(5deg)";
  }
  return (
    <div className={cn("grid justify-items-center gap-3", className)}>
      <button
        type="button"
        aria-label={cards[front].title + " — show next card"}
        className="relative h-[154px] w-[134px] touch-pan-y cursor-grab rounded-xl outline-offset-8 select-none active:cursor-grabbing"
        onPointerDown={(e) => {
          if (
            !e.isPrimary ||
            e.button !== 0 ||
            leaving.current ||
            cards.length < 2
          )
            return;
          const rect = e.currentTarget.getBoundingClientRect();
          drag.current = {
            id: e.pointerId,
            x: e.clientX,
            y: e.clientY,
            lastX: e.clientX,
            time: e.timeStamp,
            speed: 0,
            tilt: e.clientY - rect.top < rect.height / 2 ? 1 : -1,
            width: rect.width,
            travelled: false,
          };
          suppressClick.current = false;
          if (lead.current) lead.current.style.transition = "none";
          e.currentTarget.setPointerCapture(e.pointerId);
        }}
        onPointerMove={(e) => {
          const grip = drag.current;
          if (!grip || grip.id !== e.pointerId || !lead.current) return;
          const dx = e.clientX - grip.x,
            dy = e.clientY - grip.y;
          const elapsed = e.timeStamp - grip.time;
          if (elapsed > 0)
            grip.speed =
              0.5 * grip.speed +
              (0.5 * (e.clientX - grip.lastX) * 1000) / elapsed;
          grip.time = e.timeStamp;
          grip.lastX = e.clientX;
          if (Math.abs(dx) > 5 || Math.abs(dy) > 5) grip.travelled = true;
          lead.current.style.setProperty(
            "--next",
            String(Math.min(1, Math.max(0, -dx / 55))),
          );
          lead.current.style.setProperty(
            "--previous",
            String(Math.min(1, Math.max(0, dx / 55))),
          );
          if (!reduce())
            lead.current.style.transform =
              "translate(" +
              dx +
              "px," +
              dy * 0.35 +
              "px) rotate(" +
              (5 + dx * 0.065 * grip.tilt) +
              "deg)";
        }}
        onPointerCancel={() => {
          suppressClick.current = true;
          releaseCard();
        }}
        onLostPointerCapture={() => {
          if (drag.current) releaseCard();
        }}
        onPointerUp={(e) => {
          const grip = drag.current;
          if (!grip || grip.id !== e.pointerId) return;
          const dx = e.clientX - grip.x;
          // The original uses a 110px throw on a 256px card, or a quick flick.
          const flick =
            e.timeStamp - grip.time < 80 &&
            Math.abs(grip.speed) > 700 &&
            Math.sign(grip.speed) === Math.sign(dx);
          suppressClick.current = grip.travelled || Math.abs(dx) > 5;
          if (
            Math.abs(dx) > (grip.width * 110) / 256 ||
            (Math.abs(dx) > 5 && flick)
          ) {
            drag.current = null;
            if (lead.current) lead.current.style.removeProperty("transition");
            void turn(Math.sign(dx));
          } else releaseCard();
        }}
        onClick={() => {
          if (suppressClick.current) {
            suppressClick.current = false;
            return;
          }
          void turn(-1);
        }}
        onKeyDown={(e) => {
          if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
            e.preventDefault();
            void turn(e.key === "ArrowLeft" ? 1 : -1);
          }
        }}
      >
        {Array.from({ length: Math.min(3, cards.length) }, (_, depth) => {
          const pos = (front + depth) % cards.length;
          const card = cards[pos];
          return (
            <span
              key={pos}
              ref={depth === 0 ? lead : undefined}
              aria-hidden
              className="absolute inset-0 overflow-hidden rounded-[12px] border border-black/10 text-left shadow-[0_3px_4px_#0002,0_14px_17px_-10px_#0005] motion-safe:transition-[transform] duration-300 ease-out"
              style={{
                zIndex: 3 - depth,
                backgroundColor: card.color,
                color: card.ink,
                transform:
                  depth === 0
                    ? "rotate(5deg)"
                    : "translate(" +
                      -depth * 10 +
                      "px," +
                      -depth * 2 +
                      "px) rotate(" +
                      (5 - depth * 12) +
                      "deg)",
              }}
            >
              <span
                className="absolute inset-0 bg-cover bg-center grayscale"
                style={{
                  backgroundImage: card.cover
                    ? 'url("' + card.cover + '")'
                    : "repeating-radial-gradient(ellipse at 75% 15%,transparent 0 5px,currentColor 6px 8px)",
                }}
              />
              {depth === 0 && (
                <>
                  <span
                    className="absolute top-3 right-2 -rotate-6 rounded border border-white/70 bg-black/50 px-1.5 font-mono text-[9px] text-white"
                    style={{ opacity: "var(--next,0)" }}
                  >
                    NEXT
                  </span>
                  <span
                    className="absolute top-3 left-2 rotate-6 rounded border border-white/70 bg-black/50 px-1.5 font-mono text-[9px] text-white"
                    style={{ opacity: "var(--previous,0)" }}
                  >
                    BACK
                  </span>
                </>
              )}
              <span className="absolute inset-x-0 bottom-0 flex items-end justify-between bg-linear-to-t from-black/80 to-transparent px-3 pt-7 pb-2 text-white">
                <span className="font-serif text-[29px] leading-none tracking-[-.055em]">
                  {card.title}
                </span>
                <span className="font-mono text-[8px]">
                  {String(pos + 1).padStart(2, "0")}
                </span>
              </span>
            </span>
          );
        })}
      </button>
      <span className="flex items-center gap-1.5" aria-hidden>
        {cards.slice(0, 12).map((_, i) => (
          <i
            key={i}
            className={
              "h-1 rounded-full transition-[width] motion-reduce:transition-none " +
              (i === front ? "w-4 bg-primary" : "w-1 bg-foreground/25")
            }
          />
        ))}
      </span>
      <span className="sr-only" aria-live="polite">
        {cards[front].title}
      </span>
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";

import { useId, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { House, Layers, Heart, type LucideIcon } from "lucide-react";

const defaults = [
  { label: "Home", icon: House },
  { label: "Layers", icon: Layers },
  { label: "Favorites", icon: Heart },
];

export function SpringDock({
  className,
  items = defaults,
  onChange,
}: {
  className?: string;
  items?: { label: string; icon: LucideIcon }[];
  onChange?: (index: number) => void;
}) {
  const [requested, setActive] = useState(0);
  const active = Math.min(requested, Math.max(0, items.length - 1));
  const id = useId();
  const reduced = useReducedMotion();
  if (!items.length) return null;
  return (
    <div
      role="group"
      aria-label="Section switcher"
      className={cn(
        "inline-flex items-center gap-1 rounded-2xl border border-foreground/10 bg-card p-1.5 shadow-sm",
        className,
      )}
    >
      {items.map(({ label, icon: Icon }, index) => (
        <button
          type="button"
          key={label}
          aria-label={label}
          aria-pressed={active === index}
          onClick={() => {
            setActive(index);
            onChange?.(index);
          }}
          className="group relative flex h-10 cursor-pointer items-center justify-center gap-1 overflow-hidden rounded-2xl px-3"
          title={label}
        >
          {active === index && (
            <motion.span
              aria-hidden
              layoutId={id}
              className="absolute inset-0 rounded-2xl bg-primary shadow-[inset_0_1px_1px_#ffffff30,0_2px_3px_#0002]"
              transition={
                reduced
                  ? { duration: 0 }
                  : { type: "spring", stiffness: 410, damping: 27 }
              }
            />
          )}
          <Icon
            aria-hidden
            className="relative size-[21px] motion-safe:transition-transform motion-safe:group-hover:-translate-y-0.5 motion-safe:group-active:scale-90"
            strokeWidth={1.65}
            color={
              active === index
                ? "var(--primary-foreground)"
                : "var(--muted-foreground)"
            }
          />
          <motion.span
            initial={false}
            animate={{
              width: index === active ? "auto" : 0,
              opacity: index === active ? 1 : 0,
            }}
            transition={
              reduced
                ? { duration: 0 }
                : { type: "spring", stiffness: 360, damping: 30 }
            }
            aria-hidden
            className="relative overflow-hidden text-xs font-medium whitespace-nowrap text-primary-foreground"
          >
            {label}
          </motion.span>
        </button>
      ))}
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { Volume2, VolumeX } from "lucide-react";
import { panel } from "@/lib/takt-surface";
export function WaveSlider({
  className,
  label = "Volume",
  defaultValue = 60,
  value,
  onValueChange,
}: {
  className?: string;
  label?: string;
  defaultValue?: number;
  value?: number;
  onValueChange?: (value: number) => void;
}) {
  const [internal, setInternal] = useState(defaultValue);
  const level = Math.max(0, Math.min(100, value ?? internal));
  const remembered = useRef(level || 60);
  function setVolume(n: number) {
    if (value === undefined) setInternal(n);
    onValueChange?.(n);
  }
  return (
    <div
      className={cn(
        panel +
          " flex w-60 max-w-full items-center gap-2.5 rounded-full! px-2.5! py-1!",
        className,
      )}
    >
      <span className="flex shrink-0 items-center text-xs font-medium">
        <button
          type="button"
          aria-label={level === 0 ? "Unmute" : "Mute"}
          aria-pressed={level === 0}
          className="grid size-9 place-items-center rounded-full bg-muted"
          onClick={() => {
            if (level) {
              remembered.current = level;
              setVolume(0);
            } else setVolume(remembered.current);
          }}
        >
          {level === 0 ? <VolumeX size={15} /> : <Volume2 size={15} />}
        </button>
      </span>
      <span className="relative flex h-11 min-w-0 flex-1 items-center rounded focus-within:ring-1 focus-within:ring-foreground/35">
        <span
          aria-hidden
          className="relative mx-1 h-1 w-full rounded-full bg-foreground/15"
        >
          <i
            className="absolute inset-y-0 left-0 rounded-full bg-primary"
            style={{ width: level + "%" }}
          />
          <i
            className="absolute top-1/2 size-3 -translate-1/2 rounded-full bg-primary"
            style={{ left: level + "%" }}
          />
        </span>
        <input
          type="range"
          aria-label={label}
          aria-valuetext={level + "%"}
          value={level}
          className="absolute inset-0 h-full w-full cursor-ew-resize opacity-0"
          onChange={(e) => {
            const n = +e.target.value;
            setVolume(n);
          }}
        />
      </span>
      <output className="w-9 text-right font-mono text-xs tabular-nums">
        {level}%
      </output>
    </div>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";

"use client";
import { cn } from "@/lib/utils";
import { useEffect, useRef, useState } from "react";
import { Check, Fingerprint } from "lucide-react";
export function HoldButton({
  className,
  onConfirm,
  duration = 800,
  resetAfter = 1400,
}: {
  className?: string;
  onConfirm?: () => void;
  duration?: number;
  resetAfter?: number;
}) {
  const [phase, setPhase] = useState<"idle" | "holding" | "done">("idle");
  const state = useRef(phase);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  function change(p: typeof phase) {
    state.current = p;
    setPhase(p);
  }
  function clear() {
    if (timer.current !== null) clearTimeout(timer.current);
    timer.current = null;
  }
  useEffect(() => {
    function interrupt() {
      if (state.current === "holding") {
        clear();
        state.current = "idle";
        setPhase("idle");
      }
    }
    function visibility() {
      if (document.hidden) interrupt();
    }
    window.addEventListener("blur", interrupt);
    document.addEventListener("visibilitychange", visibility);
    return () => {
      window.removeEventListener("blur", interrupt);
      document.removeEventListener("visibilitychange", visibility);
      clear();
      state.current = "idle";
      setPhase("idle");
    };
  }, []);
  function start() {
    if (state.current !== "idle") return;
    change("holding");
    timer.current = setTimeout(
      () => {
        change("done");
        timer.current = setTimeout(
          () => change("idle"),
          Math.max(0, resetAfter),
        );
        onConfirm?.();
      },
      Math.max(0, duration),
    );
  }
  function cancel() {
    if (state.current === "holding") {
      clear();
      change("idle");
    }
  }
  return (
    <button
      type="button"
      className={cn(
        "relative inline-flex h-12 min-w-44 cursor-pointer touch-none items-center justify-center gap-2.5 overflow-hidden rounded-full border border-foreground/15 bg-card px-5 text-sm font-semibold text-card-foreground shadow-sm select-none",
        className,
      )}
      onPointerDown={(e) => {
        if (e.button !== 0 || !e.isPrimary) return;
        e.currentTarget.setPointerCapture(e.pointerId);
        start();
      }}
      onContextMenu={(e) => e.preventDefault()}
      onPointerUp={cancel}
      onLostPointerCapture={cancel}
      onPointerCancel={cancel}
      onBlur={cancel}
      onKeyDown={(e) => {
        if (["Enter", " "].includes(e.key)) {
          e.preventDefault();
          if (!e.repeat) start();
        }
      }}
      onKeyUp={(e) => {
        if (["Enter", " "].includes(e.key)) {
          e.preventDefault();
          cancel();
        }
      }}
    >
      <Fingerprint size={18} />
      <span aria-live="polite">
        {phase === "done" ? "Confirmed" : "Hold"}
      </span>
      <span
        aria-hidden
        className="absolute inset-0 flex items-center justify-center gap-2.5 bg-primary text-primary-foreground motion-safe:transition-[clip-path] motion-reduce:transition-none! motion-reduce:duration-0!"
        style={{
          clipPath: phase === "idle" ? "inset(0 100% 0 0)" : "inset(0 0 0 0)",
          transitionTimingFunction: "linear",
          transitionDuration: (phase === "holding" ? duration : 100) + "ms",
        }}
      >
        {phase === "done" ? <Check size={18} /> : <Fingerprint size={18} />}{" "}
        {phase === "done" ? "Confirmed" : "Hold"}
      </span>
    </button>
  );
}

"use client";
import { cn } from "@/lib/utils";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { RefreshCw } from "lucide-react";

export function RollingText({
  className,
  words = ["Hello", "Bonjour", "Hello"],
}: {
  className?: string;
  words?: string[];
}) {
  const [index, setIndex] = useState(0);
  const reduced = useReducedMotion();
  if (!words.length) return null;
  const word = words[index % words.length];
  return (
    <button
      onKeyDown={(e) => {
        if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
          e.preventDefault();
          setIndex(
            (i) =>
              (i + (e.key === "ArrowRight" ? 1 : words.length - 1)) %
              words.length,
          );
        }
      }}
      type="button"
      aria-label={word + " — change word"}
      onClick={() => setIndex((i) => i + 1)}
      className={cn(
        "inline-flex cursor-pointer items-center gap-4 overflow-hidden rounded-md px-2 py-1 text-foreground",
        className,
      )}
    >
      <span
        aria-hidden
        className="flex overflow-hidden font-serif text-[43px] leading-tight tracking-[-0.04em]"
      >
        {Array.from(word).map((letter, i) => (
          <motion.span
            key={index + "-" + i}
            initial={index && !reduced ? { y: "100%" } : false}
            animate={{ y: 0 }}
            transition={{
              duration: reduced ? 0 : 0.46,
              delay: reduced ? 0 : Math.min(i, 10) * 0.029,
            }}
          >
            {letter}
          </motion.span>
        ))}
      </span>
      <span className="grid size-8 place-items-center rounded-full bg-muted">
        <RefreshCw size={14} aria-hidden />
      </span>
    </button>
  );
}

