  defaultChecked = true,
  checked,
  onCheckedChange,
}: {
  className?: string;
  label?: string;
  defaultChecked?: boolean;
  checked?: boolean;
  onCheckedChange?: (value: boolean) => void;
}) {
  const [internal, setInternal] = useState(defaultChecked);
  const active = checked ?? internal;
  const reduced = useReducedMotion();
  const Icon = active ? Bell : BellOff;
  return (
    <button
      type="button"
