"use client";
import { cn } from "@/lib/utils";

import { useEffect, useState } from "react";
import { CalendarDays, MessageCircle, Moon, Waves } from "lucide-react";
const inbox = [
  { title: "Mira", body: "Left a comment", time: "now" },
  { title: "Calendar", body: "Design review", time: "5 min" },
];
export function FocusMode({
  className,
  onChange,
  minutes = 25,
  notifications = inbox,
}: {
  className?: string;
  onChange?: (active: boolean) => void;
  minutes?: number;
  notifications?: { title: string; body: string; time: string }[];
}) {
  const [deadline, setDeadline] = useState<number | null>(null);
  const [remaining, setRemaining] = useState(0);
  const active = deadline !== null;
  useEffect(() => {
    if (deadline === null) return;
    const update = () => {
      const left = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      setRemaining(left);
      if (left === 0) {
        setDeadline(null);
        onChange?.(false);
      }
    };
    update();
    const timer = setInterval(update, 1000);
    return () => clearInterval(timer);
  }, [deadline, onChange]);
  const clock =
    Math.floor(remaining / 60) + ":" + String(remaining % 60).padStart(2, "0");
  return (
    <div
      className={cn(
        "w-72 max-w-full rounded-2xl bg-[#1c2320] p-2 text-[#f8faf9] shadow-[inset_0_1px_0_#ffffff20,0_12px_25px_-10px_#171d1a66]",
        className,
      )}
    >
      {active && (
        <div aria-hidden className="mx-3 my-2 flex h-1 gap-[2px]">
          {Array.from({ length: 24 }, (_, i) => (
            <span
              key={i}
              className={
                "flex-1 rounded-sm " +
                (i < Math.ceil((24 * remaining) / Math.max(1, minutes * 60))
                  ? "bg-[#d6dfdb]"
                  : "bg-white/15")
              }
            />
          ))}
        </div>
      )}
      <div className="relative h-[112px] overflow-hidden rounded-[18px]">
        <div
          aria-hidden={active}
          className={
            "grid gap-1.5 motion-safe:transition-[transform,opacity] duration-300 " +
            (active ? "-translate-y-5 scale-90 opacity-0" : "")
          }
        >
          {notifications.slice(0, 2).map((n, i) => (
            <div
              key={n.title + i}
              className="flex h-[53px] items-center gap-2.5 rounded-2xl border border-white/5 bg-white/[.065] px-3"
            >
              <span
                className={
                  "grid size-8 shrink-0 place-items-center rounded-xl " +
                  (i === 0
                    ? "bg-[#d1dcd7] text-[#4c6258]"
                    : "bg-[#b4d7ca] text-[#38574e]")
                }
              >
                {i === 0 ? (
                  <MessageCircle size={16} />
                ) : (
                  <CalendarDays size={16} />
                )}
              </span>
              <span className="min-w-0 flex-1">
                <strong className="block text-xs">{n.title}</strong>
                <span className="block truncate text-[11px] text-white/65">
                  {n.body}
                </span>
              </span>
              <small className="self-start pt-2 text-[9px] text-white/55">
                {n.time}
              </small>
            </div>
          ))}
        </div>
        <div
          aria-hidden={!active}
          className={
            "pointer-events-none absolute inset-0 grid content-center justify-items-center gap-1 rounded-2xl bg-[radial-gradient(ellipse_at_50%_120%,#597468,transparent_75%)] motion-safe:transition-[opacity,transform] duration-300 " +
            (active ? "" : "translate-y-4 opacity-0")
          }
        >
          <Waves size={18} className="text-[#d7e0dc]" />
          <span
            role="timer"
            className="text-3xl font-medium tracking-tighter tabular-nums"
          >
            {clock}
          </span>
          <small className="text-[10px] text-white/65">Session remaining</small>
        </div>
      </div>
      <button
        type="button"
        aria-pressed={active}
        aria-label="Focus mode"
        className="mt-2 flex h-11 w-full items-center gap-2 rounded-[15px] bg-white/10 px-3 text-sm font-medium"
        onClick={() => {
          const seconds = Math.max(1, Math.round(minutes * 60));
          setRemaining(seconds);
          setDeadline(active ? null : Date.now() + seconds * 1000);
          onChange?.(!active);
        }}
      >
        <Moon size={16} />
        Focus
        <span
          className={
            "ml-auto flex h-5 w-9 items-center rounded-full p-[3px] transition-colors " +
            (active ? "bg-[#c0cec8]" : "bg-white/25")
          }
        >
          <i
            className={
              "size-[14px] rounded-full bg-white shadow motion-safe:transition-transform " +
              (active ? "translate-x-4" : "")
            }
          />
        </span>
      </button>
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useId, useState } from "react";
import { Bookmark, Pin, Star } from "lucide-react";
export function MorphTooltip({
  className,
  label = "Bookmark",
  onClick,
  onAction,
}: {
  className?: string;
  label?: string;
  onClick?: () => void;
  onAction?: (action: "bookmark" | "favorite" | "pin") => void;
}) {
  const [active, setActive] = useState<number | null>(null),
    [pressed, setPressed] = useState<string[]>([]);
  const id = useId();
  const actions = [
    { id: "bookmark", label, Icon: Bookmark },
    { id: "favorite", label: "Favorite", Icon: Star },
    { id: "pin", label: "Pin", Icon: Pin },
  ] as const;
  return (
    <div
      className={cn(
        "relative inline-flex items-center gap-1 rounded-xl border bg-card p-1.5 text-card-foreground shadow-sm",
        className,
      )}
      onPointerLeave={(e) => {
        const focused = [
          ...e.currentTarget.querySelectorAll("button"),
        ].findIndex((button) => button === document.activeElement);
        setActive(focused === -1 ? null : focused);
      }}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setActive(null);
      }}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-x-1.5 bottom-full mb-2 h-7"
      >
        <span
          className="absolute top-0 w-1/3 motion-safe:transition-transform motion-safe:duration-300 motion-safe:ease-out"
          style={{ transform: "translateX(" + (active ?? 0) * 100 + "%)" }}
        >
          <span
            className={
              "absolute left-1/2 -translate-x-1/2 rounded-lg bg-primary px-2.5 py-1 text-xs whitespace-nowrap text-primary-foreground shadow-sm motion-safe:transition-opacity " +
              (active === null ? "opacity-0" : "opacity-100")
            }
          >
            {actions[active ?? 0].label}
          </span>
        </span>
      </span>
      {actions.map(({ id: key, label: name, Icon }, i) => (
        <button
          key={key}
          type="button"
          aria-label={name}
          aria-pressed={pressed.includes(key)}
          aria-describedby={active === i ? id : undefined}
          className="grid size-10 place-items-center rounded-xl hover:bg-muted focus-visible:bg-muted aria-pressed:bg-muted aria-pressed:[&>svg]:fill-current motion-safe:active:scale-90"
          onFocus={() => setActive(i)}
          onPointerEnter={() => setActive(i)}
          onKeyDown={(e) => {
            if (e.key === "Escape") setActive(null);
          }}
          onClick={() => {
            setActive(i);
            setPressed((list) =>
              list.includes(key)
                ? list.filter((value) => value !== key)
                : [...list, key],
            );
            if (i === 0) onClick?.();
            onAction?.(key);
          }}
        >
          <Icon size={17} />
        </button>
      ))}
      {active !== null && (
        <span id={id} role="tooltip" className="sr-only">
          {actions[active].label}
        </span>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Check, Terminal } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel } from "@/lib/takt-surface";

export function CommandButton({
  className,
  label = "Run",
  onExecute,
}: {
  className?: string;
  label?: string;
  onExecute?: () => void;
}) {
  const button = useRef<HTMLButtonElement>(null);
  const [count, setCount] = useState(0);
  const [held, setHeld] = useState(false);
  useEffect(() => {
    function down(event: KeyboardEvent) {
      if (
        event.defaultPrevented ||
        event.isComposing ||
        event.altKey ||
        event.shiftKey ||
        !(event.metaKey || event.ctrlKey) ||
        event.key !== "Enter"
      )
        return;
      if (
        document.querySelector('[role="dialog"], dialog[open]') ||
        (event.target instanceof HTMLElement &&
          event.target.closest("input,textarea,[contenteditable=true]"))
      )
        return;
      event.preventDefault();
      if (!event.repeat) {
        setHeld(true);
        button.current?.click();
      }
    }
    function release() {
      setHeld(false);
    }
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", release);
    window.addEventListener("blur", release);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", release);
      window.removeEventListener("blur", release);
    };
  }, []);
  return (
    <button
      ref={button}
      type="button"
      aria-keyshortcuts="Meta+Enter Control+Enter"
      title="⌘ / Ctrl + Enter"
      data-held={held}
      onClick={() => {
        setCount((n) => n + 1);
        onExecute?.();
      }}
      className={cn(
        panel + " group inline-flex items-center gap-2.5 py-2.5",
        className,
      )}
    >
      <span
        key={count}
        className="grid size-7 place-items-center rounded-lg bg-primary text-primary-foreground motion-safe:animate-in motion-safe:zoom-in-75"
      >
        {count ? <Check size={15} /> : <Terminal size={15} />}
      </span>
      <span className="font-medium">{label}</span>
      <kbd
        aria-hidden
        className="rounded-md border border-foreground/15 border-b-2 bg-muted px-2 py-1 font-mono text-[11px] text-foreground/75 group-active:border-b group-data-[held=true]:border-b motion-safe:transition-transform motion-safe:group-active:translate-y-px motion-safe:group-data-[held=true]:translate-y-px"
      >
        ⌘/Ctrl ↵
      </kbd>
      <output
        aria-label="Run count"
        className="min-w-3 font-mono text-[10px] tabular-nums text-muted-foreground"
      >
        {count}
      </output>
    </button>
  );
}

