            {status !== undefined && unlocked
              ? "Access granted"
              : captions[phase]}
          </span>
        </span>
      </button>
      <div className="mt-4 flex items-center gap-2.5 border-t pt-3">
        <span
          aria-hidden
          className="grid size-8 shrink-0 place-items-center rounded-lg bg-muted"
        >
          <FileText size={15} />
        </span>
        <span className="grid min-w-0 flex-1 gap-0.5 text-xs">
          <span
            className={cn(
              "truncate font-semibold motion-safe:transition-[filter,opacity] motion-safe:duration-400",
              !unlocked && "opacity-50 blur-[3px] select-none",
            )}
            aria-hidden={!unlocked}
          >
            Project brief.fig
          </span>
          <span className="text-[10px] text-muted-foreground">
            {unlocked
              ? "Access granted"
              : phase === "error"
                ? "Face not recognized"
                : "Locked file"}
          </span>
        </span>
        {unlocked ? (
          <LockKeyholeOpen
            aria-hidden
            size={15}
            className="text-emerald-700 dark:text-emerald-300"
          />
        ) : (
          <LockKeyhole
            aria-hidden
            size={15}
