"use client";

import { useLayoutEffect, useRef } from "react";

// The advancing edge reaches its stop before the trailing edge catches up.
export function ElasticIndicator({
  index,
  count,
  className = "bg-primary",
}: {
  index: number;
  count: number;
  className?: string;
}) {
  const pill = useRef<HTMLSpanElement>(null);
  const previous = useRef(index);
  useLayoutEffect(() => {
    const node = pill.current;
    if (!node || !count) return;
    const slot = Math.min(count - 1, Math.max(0, index));
    node.style.transitionDuration =
      slot >= previous.current ? "370ms, 190ms" : "190ms, 370ms";
    node.style.left = (100 * slot) / count + "%";
    node.style.right = (100 * (count - slot - 1)) / count + "%";
    previous.current = slot;
  }, [index, count]);
  return count > 0 ? (
    <span
      aria-hidden
      ref={pill}
      className={
        "pointer-events-none absolute inset-y-0 rounded-[inherit] ease-[cubic-bezier(.19,1,.32,1)] motion-safe:transition-[left,right] motion-reduce:transition-none! motion-reduce:duration-0! " +
        className
      }
    />
  ) : null;
}

"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { House, Folder, Calendar, Image as Picture } from "lucide-react";
import { ElasticIndicator } from "@/lib/takt-indicator";
const tools = [
  { name: "Home", Icon: House },
  { name: "Files", Icon: Folder },
  { name: "Calendar", Icon: Calendar },
  { name: "Photo", Icon: Picture },
];
export function RubberDock({
  className,
  onSelect,
}: {
  className?: string;
  onSelect?: (index: number) => void;
}) {
  const [selected, setSelected] = useState(0);
  const [preview, setPreview] = useState<number | null>(null);
  const pointer = useRef<number | null>(null);
  const rail = useRef<HTMLDivElement>(null);
  function slot(x: number) {
    const rect = rail.current!.getBoundingClientRect();
    return Math.max(
      0,
      Math.min(3, Math.floor((4 * (x - rect.left)) / rect.width)),
    );
  }
  function apply(index: number) {
    setSelected(index);
    onSelect?.(index);
  }
  const shown = preview ?? selected;
  return (
    <div className={cn("grid justify-items-center gap-2", className)}>
      <div className="rounded-2xl border border-foreground/10 bg-card p-1.5 text-card-foreground shadow-sm">
        <div
          ref={rail}
          role="group"
          aria-label="App dock"
          className="relative flex touch-pan-y rounded-2xl"
          onPointerDown={(e) => {
            if (e.button !== 0 || !e.isPrimary) return;
            pointer.current = e.pointerId;
            setPreview(slot(e.clientX));
          }}
          onPointerMove={(e) => {
            if (pointer.current === e.pointerId) {
              e.currentTarget.setPointerCapture(e.pointerId);
              setPreview(slot(e.clientX));
            }
          }}
          onPointerUp={(e) => {
            if (pointer.current !== e.pointerId) return;
            pointer.current = null;
            setPreview(null);
            apply(slot(e.clientX));
          }}
          onPointerCancel={() => {
            pointer.current = null;
            setPreview(null);
          }}
          onPointerLeave={(e) => {
            if (!e.currentTarget.hasPointerCapture(e.pointerId)) {
              pointer.current = null;
              setPreview(null);
            }
          }}
        >
          <ElasticIndicator
            index={shown}
            count={tools.length}
            className="bg-primary shadow-sm"
          />
          {tools.map(({ name, Icon }, i) => (
            <button
              key={name}
              type="button"
              aria-label={name}
              aria-pressed={selected === i}
              onClick={(e) => {
                if (e.detail === 0) apply(i);
              }}
              className={
                "relative grid size-11 place-items-center rounded-2xl " +
                (shown === i
                  ? "text-primary-foreground"
                  : "text-muted-foreground")
              }
            >
              <Icon size={18} />
            </button>
          ))}
        </div>
      </div>
      <output className="text-xs font-medium text-muted-foreground">
        {tools[shown].name}
      </output>
    </div>
  );
}

"use client";
import { useActionFocus } from "@/lib/takt-focus";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
} from "@/lib/takt-surface";

import { useState } from "react";
import { Menu, ChevronRight } from "lucide-react";

export function DynamicMenu({
  className,
  formats = ["PDF", "SVG"],
  onChoose,
}: {
  className?: string;
  formats?: string[];
  onChoose?: (format: string) => void;
}) {
  const { root, focusAfterRender } = useActionFocus<HTMLDivElement>();
  const [view, setView] = useState<"closed" | "root" | "more">("closed");
  const [choice, setChoice] = useState("");
  return (
    <div
      ref={root}
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          e.preventDefault();
          focusAfterRender(
            view === "more" ? "[data-export]" : "[aria-expanded]",
          );
          setView(view === "more" ? "root" : "closed");
        }
      }}
      className={cn(
        surfacePanel +
          " grid max-w-full gap-1.5 motion-safe:transition-[width] motion-safe:duration-300 motion-safe:ease-out " +
          (view === "more" ? "w-60" : "w-44"),
        className,
      )}
    >
      <button
        type="button"
        className={surfaceSecondary}
        aria-expanded={view !== "closed"}
        onClick={() => setView(view === "closed" ? "root" : "closed")}
      >
        <Menu size={15} />
        {choice || "Menu"}
      </button>
      {view === "root" && (
        <button
          type="button"
          className={surfaceSecondary}
          data-export
          onClick={() => {
            focusAfterRender("[data-back]");
            setView("more");
          }}
        >
          Export <ChevronRight size={14} />
        </button>
      )}
      {view === "more" && (
        <div className="flex flex-wrap gap-2 motion-safe:animate-in motion-safe:slide-in-from-right-2">
          <button
            type="button"
            className={surfaceSecondary}
            aria-label="Back"
            data-back
            onClick={() => {
              focusAfterRender("[data-export]");
              setView("root");
            }}
          >
            ←
          </button>
          {formats.map((f) => (
            <button
              type="button"
              key={f}
              className={surfaceSecondary}
              onClick={() => {
                focusAfterRender("[aria-expanded]");
                setChoice(f);
                onChoose?.(f);
                setView("closed");
              }}
            >
              {f}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

