"use client";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { panel } from "@/lib/takt-surface";
export function PaginationDots({
  className,
  pages = 5,
  onChange,
}: {
  className?: string;
  pages?: number;
  onChange?: (index: number) => void;
}) {
  const [selected, setSelected] = useState(0);
  const total = Number.isFinite(pages) ? Math.max(0, Math.floor(pages)) : 0;
  const index = Math.max(0, Math.min(total - 1, selected));
  const start = Math.max(0, Math.min(index - 2, total - 5));
  function select(i: number) {
    if (i < 0 || i >= total) return;
    setSelected(i);
    onChange?.(i);
  }
  return (
    <div className={cn(panel + " grid justify-items-center gap-2", className)}>
      <output className="font-mono text-lg tabular-nums">
        {total ? String(index + 1).padStart(2, "0") : "00"}{" "}
        <span className="text-xs text-muted-foreground">/ {total}</span>
      </output>
      <div
        className="flex items-center gap-1"
        onKeyDown={(e) => {
          const n = (
            {
              Home: 0,
              End: total - 1,
              ArrowRight: Math.min(index + 1, total - 1),
              ArrowLeft: Math.max(0, index - 1),
            } as Record<string, number>
          )[e.key];
          if (n !== undefined && total) {
            e.preventDefault();
            select(n);
            const node = e.currentTarget;
            requestAnimationFrame(() =>
              node
                .querySelector<HTMLButtonElement>('[aria-current="page"]')
                ?.focus(),
            );
          }
        }}
      >
        {Array.from({ length: Math.min(total, 5) }, (_, i) => i + start).map(
          (i) => (
            <button
              key={i}
              type="button"
              tabIndex={i === index ? 0 : -1}
              aria-label={"Page " + (i + 1)}
              aria-current={i === index ? "page" : undefined}
              onClick={() => select(i)}
              className="grid h-9 min-w-5 place-items-center rounded-full px-1"
            >
              <i
                className={
                  "h-2 rounded-full bg-primary motion-safe:transition-[width,opacity] motion-safe:duration-300 " +
                  (i === index ? "w-6" : "w-2 opacity-35")
                }
              />
            </button>
          ),
        )}
      </div>
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
  field as surfaceField,
} from "@/lib/takt-surface";

import { useState, useRef } from "react";
import { Search, ArrowDownLeft, Command } from "lucide-react";

export function CommandPalette({
  className,
  commands = ["New project", "Find file", "Settings"],
  onExecute,
}: {
  className?: string;
  commands?: string[];
  onExecute?: (command: string) => void;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [last, setLast] = useState("");
  const ordered =
    last && commands.includes(last)
      ? [last, ...commands.filter((c) => c !== last)]
      : commands;
  const filtered = ordered.filter((x) =>
    x.toLocaleLowerCase().includes(query.toLocaleLowerCase()),
  );
  function select(value: string) {
    onExecute?.(value);
    setLast(value);
    dialog.current?.close();
  }
  return (
    <>
      <button
        type="button"
        className={cn(surfacePanel + " flex items-center gap-3", className)}
        onClick={() => {
          setQuery("");
          setActive(0);
          dialog.current?.showModal();
        }}
      >
        <Search size={17} />
        {last || "Command palette"}{" "}
        <Command size={13} aria-hidden className="text-muted-foreground" />
      </button>
      <dialog
        ref={dialog}
        aria-label="Command palette"
        className="fixed inset-0 m-auto max-h-[80dvh] w-80 max-w-[calc(100vw-2rem)] rounded-2xl border bg-popover p-3 text-popover-foreground shadow-xl backdrop:bg-black/40"
      >
        <input
          aria-label="Search commands"
          className={surfaceField}
          placeholder="Find a command"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing || e.keyCode === 229) return;
            if (!filtered.length) return;
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              e.preventDefault();
              setActive(
                (i) =>
                  (i + (e.key === "ArrowDown" ? 1 : -1) + filtered.length) %
                  filtered.length,
              );
            }
            if (e.key === "Enter" && filtered[active]) {
              e.preventDefault();
              select(filtered[active]);
            }
          }}
        />
        <div className="my-2 grid max-h-[45dvh] gap-0.5 overflow-y-auto">
          {filtered.map((c, i) => (
            <button
              type="button"
              key={c}
              className={
                "flex items-center justify-between rounded-lg px-3 py-2 text-left text-sm hover:bg-muted " +
                (i === active ? "bg-muted font-medium" : "")
              }
              onClick={() => select(c)}
            >
              <span>
                {c}
                {c === last && (
                  <small className="ml-2 text-[9px] font-normal text-muted-foreground">
                    Recent
                  </small>
                )}
              </span>
              {i === active && <ArrowDownLeft size={13} aria-hidden />}
            </button>
          ))}
          {!filtered.length && <span>No matches</span>}
        </div>
        <button
          type="button"
          className={surfaceSecondary}
          onClick={() => dialog.current?.close()}
        >
          Close
        </button>
      </dialog>
    </>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowRight, Check, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel } from "@/lib/takt-surface";

const ordinal = (index: number) => String(index + 1).padStart(2, "0");

export function StepProgress({
  className,
  steps = ["Details", "Design", "Review"],
  onChange,
}: {
  className?: string;
  steps?: string[];
  onChange?: (index: number) => void;
}) {
  const [requested, setStep] = useState(0);
  const [direction, setDirection] = useState(1);
  const viewport = useRef<HTMLDivElement>(null);
  const step = Math.min(requested, Math.max(0, steps.length - 1));
  const last = step === steps.length - 1;

  useEffect(() => {
    const rail = viewport.current;
    if (!rail || rail.scrollWidth <= rail.clientWidth) return;
    const center = (step + 0.5) * rail.scrollWidth / steps.length;
    rail.scrollTo({
      left: center - rail.clientWidth / 2,
      behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth",
    });
  }, [step, steps.length]);

  function select(index: number) {
    setDirection(index >= step ? 1 : -1);
    setStep(index);
    onChange?.(index);
  }

  if (!steps.length) return null;
  return (
    <div className={cn(panel, "w-full max-w-72 min-w-0 overflow-hidden rounded-[1.35rem] p-0", className)}>
      <div className="flex items-center justify-between gap-3 px-5 pt-5 pb-4">
        <div className="min-w-0" role="status" aria-atomic="true">
          <div className="flex items-baseline gap-2 font-mono text-[10px] leading-4 font-medium tracking-widest text-muted-foreground uppercase">
            <span>Step</span>
            <span className="tabular-nums">
              <span className="text-card-foreground">{ordinal(step)}</span>
              <span className="px-1" aria-hidden="true">/</span>
              <span className="sr-only"> from </span>{ordinal(steps.length - 1)}
            </span>
          </div>
          <div className="mt-1 overflow-hidden">
            <span
              key={step}
              className={cn(
                "block text-[clamp(1.35rem,5vw,1.65rem)] leading-tight font-semibold tracking-[-0.045em] wrap-anywhere motion-safe:transition-[translate,opacity] motion-safe:duration-300 motion-safe:ease-out motion-safe:starting:opacity-0",
                direction > 0 ? "motion-safe:starting:translate-y-2" : "motion-safe:starting:-translate-y-2",
              )}
            >
              {steps[step]}
            </span>
          </div>
        </div>
        <button
          type="button"
          aria-label={last ? "Restart" : "Next"}
          title={last ? "Restart" : "Next"}
          onClick={() => select(last ? 0 : step + 1)}
          className="group grid size-11 shrink-0 cursor-pointer place-items-center rounded-full border border-foreground/15 bg-card text-card-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[background-color,transform] motion-safe:active:scale-95"
        >
          {last ? <RotateCcw size={18} aria-hidden="true" /> : (
            <ArrowRight size={19} aria-hidden="true" className="motion-safe:transition-transform motion-safe:group-hover:translate-x-0.5" />
          )}
        </button>
      </div>

      <div
        ref={viewport}
        role="group"
        aria-label="Go to step"
        className="overflow-x-auto border-t border-foreground/10 bg-muted/50 [scrollbar-width:thin]"
      >
        <div className="relative flex" style={{ minWidth: steps.length * 44 }}>
          {steps.map((label, index) => (
            <button
              key={index}
              type="button"
              aria-label={label}
              aria-current={index === step ? "step" : undefined}
              title={label}
              onClick={() => select(index)}
              className="group relative flex h-[3.75rem] min-w-0 flex-1 cursor-pointer flex-col items-center pt-2 text-muted-foreground outline-offset-[-4px] hover:text-foreground"
            >
              <span aria-hidden="true" className="flex h-6 items-center gap-0.5 font-mono text-[11px] font-medium tabular-nums">
                {index < step && <Check size={11} strokeWidth={2.4} />}
                {ordinal(index)}
              </span>
              <span aria-hidden="true" className="absolute inset-x-0 bottom-2 h-[5px] bg-repeat-x text-foreground/25 [background-image:linear-gradient(90deg,transparent_calc(50%-0.5px),currentColor_calc(50%-0.5px),currentColor_calc(50%+0.5px),transparent_calc(50%+0.5px))] [background-size:12.5%_100%]" />
              <span aria-hidden="true" className="absolute bottom-2 h-2.5 w-px bg-foreground/40" />
            </button>
          ))}
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-y-0 left-0 flex flex-col items-center pt-2 motion-safe:transition-transform motion-safe:duration-[440ms] motion-safe:ease-[cubic-bezier(.22,1,.36,1)]"
            style={{ width: `${100 / steps.length}%`, transform: `translateX(${step * 100}%)` }}
          >
            <span className="grid h-6 min-w-9 place-items-center rounded-lg bg-primary px-1.5 font-mono text-xs font-semibold text-primary-foreground tabular-nums shadow-sm">
              {ordinal(step)}
            </span>
            <span className="h-[3px] w-1.5 bg-primary [clip-path:polygon(0_0,100%_0,50%_100%)]" />
            <span className="absolute bottom-2 h-3 w-0.5 rounded-full bg-primary" />
          </div>
        </div>
      </div>
    </div>
  );
}

