"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { LayoutGroup, motion, useReducedMotion } from "motion/react";
import {
  ArrowUp,
  Check,
  LoaderCircle,
  MessageSquareText,
  X,
} from "lucide-react";
import { cn } from "@/lib/utils";

type Phase = "idle" | "open" | "sending" | "sent";
export function MorphPopover({
  className,
  title = "Feedback",
  children,
  onSubmit,
}: {
  className?: string;
  title?: string;
  children?: ReactNode;
  onSubmit?: (text: string) => void | Promise<void>;
}) {
  const [phase, setPhase] = useState<Phase>("idle"),
    [text, setText] = useState(""),
    [error, setError] = useState(false);
  const root = useRef<HTMLDivElement>(null),
    trigger = useRef<HTMLButtonElement>(null),
    field = useRef<HTMLTextAreaElement>(null),
    close = useRef<HTMLButtonElement>(null);
  const sending = useRef(false),
    restore = useRef(false),
    confirmed = useRef<HTMLDivElement>(null);
  const id = useId(),
    reduced = useReducedMotion(),
    open = phase === "open" || phase === "sending";
  const transition = reduced
    ? { duration: 0 }
    : { type: "spring" as const, duration: 0.42, bounce: 0.14 };
  function collapse(focus: boolean) {
    restore.current = focus;
    setPhase("idle");
  }
  useEffect(() => {
    if (phase === "idle" && restore.current) {
      trigger.current?.focus({ preventScroll: true });
      restore.current = false;
    }
    if (phase === "sent") {
      if (restore.current) confirmed.current?.focus({ preventScroll: true });
      const timer = setTimeout(
        () => collapse(!!root.current?.contains(document.activeElement)),
        1600,
      );
      return () => clearTimeout(timer);
    }
  }, [phase]);
  useEffect(() => {
    if (!open) return;
    (field.current ?? close.current)?.focus({ preventScroll: true });
    function outside(e: PointerEvent) {
      if (
        !sending.current &&
        e.target instanceof Node &&
        !root.current?.contains(e.target)
      )
        collapse(false);
    }
    document.addEventListener("pointerdown", outside);
    return () => document.removeEventListener("pointerdown", outside);
  }, [open]);
  async function send() {
    const value = text.trim();
    if (!value || sending.current) return;
    sending.current = true;
    setError(false);
    setPhase("sending");
    try {
      if (onSubmit) await onSubmit(value);
      else await new Promise((resolve) => setTimeout(resolve, 550));
      restore.current = !!root.current?.contains(document.activeElement);
      setText("");
      setPhase("sent");
    } catch {
      setError(true);
      setPhase("open");
      field.current?.focus({ preventScroll: true });
    } finally {
      sending.current = false;
    }
  }
  const label = (
    <motion.span
      layoutId={id + "-label"}
      transition={transition}
      className="inline-flex items-center gap-2 whitespace-nowrap text-[13px] font-semibold"
    >
      <MessageSquareText size={15} />
      {title}
    </motion.span>
  );
  return (
    <LayoutGroup id={id}>
      <motion.div
        ref={root}
        layout
        transition={transition}
        style={{ borderRadius: open ? 18 : 24 }}
        className={cn(
          "max-w-full border bg-card text-card-foreground shadow-[0_2px_4px_#0000000a,0_8px_20px_-12px_#0005]",
          open && "w-[288px]",
          className,
        )}
        onKeyDown={(e) => {
          if (e.key === "Escape" && phase === "open") {
            e.stopPropagation();
            collapse(true);
          }
          if (
            e.key === "Enter" &&
            (e.metaKey || e.ctrlKey) &&
            open &&
            children == null &&
            !e.nativeEvent.isComposing
          ) {
            e.preventDefault();
            void send();
          }
        }}
      >
        {phase === "idle" ? (
          <button
            ref={trigger}
            type="button"
            aria-expanded={false}
            onClick={() => {
              setError(false);
              setPhase("open");
            }}
            className="flex h-10 items-center rounded-full px-4"
          >
            {label}
          </button>
        ) : phase === "sent" ? (
          <div
            ref={confirmed}
            role="status"
            tabIndex={-1}
            className="flex h-10 items-center gap-2 rounded-full px-4 text-[13px] font-semibold"
          >
            <span className="grid size-5 place-items-center rounded-full bg-emerald-600/15 text-emerald-700 dark:text-emerald-300">
              <Check size={13} />
            </span>
            Thanks for your feedback
          </div>
        ) : (
          <div className="p-3">
            <div className="mb-2 flex items-center justify-between gap-2 pl-1">
              {label}
              <button
                ref={close}
                type="button"
                aria-label="Close"
                aria-disabled={phase === "sending"}
                onClick={() => {
                  if (!sending.current) collapse(true);
                }}
                className="grid size-7 place-items-center rounded-full text-muted-foreground hover:bg-muted"
              >
                <X size={14} />
              </button>
            </div>
            {children ?? (
              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  void send();
                }}
                aria-busy={phase === "sending"}
              >
                <textarea
                  ref={field}
                  aria-label="Feedback message"
                  placeholder="What could we improve?"
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  readOnly={phase === "sending"}
                  className="block h-[74px] w-full resize-none rounded-xl border bg-muted/55 px-3 py-2 text-sm placeholder:text-muted-foreground focus:border-foreground/45 focus:outline-none!"
                />
                <div className="mt-2 flex items-center justify-between gap-2">
                  {error ? (
                    <span role="alert" className="text-[11px] text-destructive">
                      Could not send
                    </span>
                  ) : (
                    <kbd
                      aria-hidden
                      className="pl-1 text-[10px] text-muted-foreground"
                    >
                      Ctrl / ⌘ ↵
                    </kbd>
                  )}
                  <button
                    type="submit"
                    disabled={!text.trim()}
                    aria-disabled={phase === "sending" || !text.trim()}
                    className="flex h-8 items-center gap-1.5 rounded-full bg-primary px-3 text-xs font-semibold text-primary-foreground disabled:opacity-40"
                  >
                    {phase === "sending" ? (
                      <>
                        <LoaderCircle
                          size={13}
                          className="motion-safe:animate-spin"
                        />
                        Sending…
                      </>
                    ) : (
                      <>
                        Send
                        <ArrowUp size={13} />
                      </>
                    )}
                  </button>
                </div>
              </form>
            )}
          </div>
        )}
      </motion.div>
    </LayoutGroup>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useRef, useState, useId } from "react";
import { panel, field } from "@/lib/takt-surface";

const graphemes =
  typeof Intl.Segmenter === "function"
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;
function characters(value: string) {
  return graphemes
    ? Array.from(graphemes.segment(value), (part) => part.segment)
    : Array.from(value);
}

export function LetterLimit({
  className,
  label = "Note",
  limit = 80,
  onChange,
}: {
  className?: string;
  label?: string;
  limit?: number;
  onChange?: (text: string) => void;
}) {
  const [text, setText] = useState("");
  const [discard, setDiscard] = useState({ letters: "", revision: 0 });
  const composing = useRef(false);
  const countId = useId();
  const max = Number.isFinite(limit) ? Math.max(0, Math.floor(limit)) : 80;
  const size = characters(text).length;
  const left = Math.max(0, max - size);
  function commit(raw: string) {
    const chars = characters(raw);
    const next = chars.slice(0, max).join("");
    if (chars.length > max)
      setDiscard((old) => ({
        revision: old.revision + 1,
        letters: chars.slice(max, max + 5).join(""),
      }));
    setText(next);
    onChange?.(next);
  }
  return (
    <label
      className={cn(
        panel + " relative grid w-64 max-w-full gap-2 overflow-hidden",
        className,
      )}
    >
      <span className="flex items-center justify-between gap-3">
        <strong>{label}</strong>
        <span
          aria-hidden
          className={
            "grid size-7 place-items-center rounded-full " +
            (left < 10 ? "text-foreground" : "text-emerald-600")
          }
          style={{
            background:
              "conic-gradient(currentColor " +
              Math.min(100, (100 * size) / Math.max(1, max)) +
              "%,var(--muted) 0)",
          }}
        >
          <i className="size-5 rounded-full bg-card" />
        </span>
      </span>
      <textarea
        rows={2}
        className={field + " resize-none py-2"}
        value={text}
        aria-label={label}
        aria-describedby={countId}
        onCompositionStart={() => {
          composing.current = true;
        }}
        onCompositionEnd={(e) => {
          composing.current = false;
          commit(e.currentTarget.value);
        }}
        onChange={(e) => {
          if (composing.current) setText(e.target.value);
          else commit(e.target.value);
        }}
      />
      <span className="flex min-h-5 items-center justify-between">
        <span
          aria-hidden
          key={discard.revision}
          onAnimationEnd={() => setDiscard((old) => ({ ...old, letters: "" }))}
          className="pointer-events-none font-mono text-xs text-muted-foreground motion-safe:animate-out motion-safe:slide-out-to-bottom-4 motion-safe:fade-out motion-safe:duration-500 motion-reduce:hidden"
        >
          {discard.letters}
        </span>
        <small
          id={countId}
          className={
            "ml-auto font-mono text-[10px] tabular-nums " +
            (left < 10 ? "font-semibold" : "text-muted-foreground")
          }
        >
          {left === 0 ? "Limit reached" : size + " / " + max}
        </small>
      </span>
    </label>
  );
}

"use client";
import { useActionFocus } from "@/lib/takt-focus";
import { cn } from "@/lib/utils";
import { useEffect, useRef, useState } from "react";
import { Upload, X } from "lucide-react";
function FileMark({ file }: { file: File }) {
  const tile = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const el = tile.current;
    if (
      !el ||
      ![
        "image/jpeg",
        "image/png",
        "image/webp",
        "image/gif",
        "image/avif",
      ].includes(file.type)
    )
      return;
    const url = URL.createObjectURL(file);
    el.style.backgroundImage = 'url("' + url + '")';
    return () => {
      el.style.removeProperty("background-image");
      URL.revokeObjectURL(url);
    };
  }, [file]);
  return (
    <span
      ref={tile}
      aria-hidden
      className="grid size-6 shrink-0 place-items-center rounded-md border bg-muted bg-cover bg-center text-[8px] font-semibold uppercase"
    >
      {!file.type.startsWith("image/") &&
        (file.name.split(".").at(-1) ?? "").slice(0, 3)}
    </span>
  );
}
export function FileDrop({
  className,
  onFiles,
}: {
  className?: string;
  onFiles?: (files: File[]) => void;
}) {
  const { root, focusAfterRender } = useActionFocus<HTMLDivElement>();
  const [files, setFiles] = useState<File[]>([]);
  const [over, setOver] = useState(false);
  const depth = useRef(0);
  function receive(next: File[]) {
    setFiles(next);
    onFiles?.(next);
  }
  return (
    <div
      ref={root}
      className={cn(
        "w-72 max-w-full rounded-xl border bg-card p-2 shadow-sm",
        className,
      )}
    >
      <label
        className={
          "group relative grid min-h-20 cursor-pointer grid-cols-[36px_1fr] items-center gap-x-3 rounded-lg border p-3 text-sm motion-safe:transition-[border-color,background-color] focus-within:outline-2 " +
          (over
            ? "border-primary bg-primary/10"
            : "border-transparent bg-muted/45 text-card-foreground")
        }
        onDragEnter={(e) => {
          e.preventDefault();
          if (!e.dataTransfer.types.includes("Files")) return;
          depth.current++;
          setOver(true);
        }}
        onDragOver={(e) => e.preventDefault()}
        onDragLeave={() => {
          depth.current = Math.max(0, depth.current - 1);
          setOver(depth.current > 0);
        }}
        onDrop={(e) => {
          e.preventDefault();
          depth.current = 0;
          setOver(false);
          if (e.dataTransfer.files.length)
            receive(Array.from(e.dataTransfer.files));
        }}
      >
        <span
          aria-hidden
          className="row-span-2 grid size-9 place-items-center rounded-lg border bg-background"
        >
          <Upload size={17} className={over ? "-translate-y-1" : ""} />
        </span>
        <strong className="self-end text-sm">
          {over
            ? "Drop your files"
            : files.length
              ? "Replace files"
              : "Attach files"}
        </strong>
        <small className="self-start text-xs text-muted-foreground">
          Drop files here or{" "}
          <span className="underline underline-offset-2">browse</span>
        </small>
        <input
          aria-label="Choose files"
          type="file"
          multiple
          className="sr-only"
          onChange={(e) => {
            if (e.target.files?.length) receive(Array.from(e.target.files));
            e.target.value = "";
          }}
        />
      </label>
      {files.length > 0 && (
        <ul
          aria-label="Selected files"
          className="mt-1.5 max-h-16 space-y-1 overflow-y-auto"
        >
          {files.map((f, i) => (
            <li
              key={f.name + i}
              className="flex items-center gap-2 rounded-lg border bg-card px-2 py-1 text-xs text-card-foreground motion-safe:animate-in motion-safe:slide-in-from-bottom-1"
            >
              <FileMark file={f} />
              <span className="min-w-0 flex-1 truncate">{f.name}</span>
              <small>{Math.ceil(f.size / 1024)} KB</small>
              <button
                type="button"
                aria-label={"Remove " + f.name}
                className="p-1"
                data-file-index={i}
                onClick={() => {
                  focusAfterRender(
                    files.length === 1
                      ? "input"
                      : '[data-file-index="' +
                          Math.min(i, files.length - 2) +
                          '"]',
                  );
                  receive(files.filter((_, j) => j !== i));
                }}
              >
                <X size={13} />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

