"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  field as surfaceField,
} from "@/lib/takt-surface";

import { useState } from "react";

export function TagInput({
  className,
  initial = ["Motion"],
  onChange,
}: {
  className?: string;
  initial?: string[];
  onChange?: (tags: string[]) => void;
}) {
  const [tags, setTags] = useState(initial);
  const [draft, setDraft] = useState("");
  function change(next: string[]) {
    setTags(next);
    onChange?.(next);
  }
  return (
    <form
      className={cn(surfacePanel + " grid w-56 gap-2", className)}
      onSubmit={(e) => {
        e.preventDefault();
        const t = draft.trim();
        if (
          t &&
          !tags.some((tag) => tag.toLocaleLowerCase() === t.toLocaleLowerCase())
        )
          change([...tags, t]);
        setDraft("");
      }}
    >
      <div className="flex max-h-16 flex-wrap gap-1 overflow-auto">
        {tags.map((t) => (
          <button
            type="button"
            key={t}
            aria-label={"Delete " + t}
            className="min-h-8 rounded-md border border-foreground/10 bg-muted px-2.5 py-1 hover:bg-accent text-xs motion-safe:animate-in motion-safe:zoom-in"
            onClick={() => change(tags.filter((x) => x !== t))}
          >
            {t} ×
          </button>
        ))}
      </div>
      <input
        aria-label="New tag"
        className={surfaceField}
        placeholder="Tag + Enter"
        onKeyDown={(e) => {
          if (e.nativeEvent.isComposing || e.keyCode === 229) return;
          if (e.nativeEvent.isComposing) return;
          if (e.key === "Backspace" && !draft && tags.length) {
            e.preventDefault();
            change(tags.slice(0, -1));
          }
          if (e.key === "," && draft.trim()) {
            e.preventDefault();
            e.currentTarget.form?.requestSubmit();
          }
        }}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
      />
    </form>
  );
}

"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  field as surfaceField,
} from "@/lib/takt-surface";

import { useId, useState } from "react";

export function PasswordStrength({
  className,
  onChange,
}: {
  className?: string;
  onChange?: (value: string) => void;
}) {
  const [value, setValue] = useState("");
  const hint = useId();
  const rules = ["8 characters", "Uppercase letter", "Digit", "Special character"];
  const checks = [
    Array.from(value).length >= 8,
    /\p{Lu}/u.test(value),
    /[0-9]/.test(value),
    /[^\p{L}\d]/u.test(value),
  ];
  const score = checks.filter(Boolean).length;
  return (
    <label
      className={cn(surfacePanel + " grid w-60 max-w-full gap-2.5", className)}
    >
      Password
      <input
        className={surfaceField}
        aria-label="Password"
        aria-describedby={hint}
        type="password"
        autoComplete="new-password"
        value={value}
        onChange={(e) => {
          setValue(e.target.value);
          onChange?.(e.target.value);
        }}
      />
      <span className="flex gap-1">
        {[1, 2, 3, 4].map((i) => (
          <i
            title={rules[i - 1]}
            key={i}
            className={
              "h-1 flex-1 rounded motion-safe:transition-colors " +
              (checks[i - 1]
                ? "bg-emerald-600 dark:bg-emerald-400"
                : "bg-muted")
            }
          />
        ))}
      </span>
      <small
        id={hint}
        aria-live="polite"
        className="min-h-8 text-xs leading-4 text-muted-foreground"
      >
        {score === 4
          ? "All requirements met"
          : (value ? "Remaining: " : "") +
            rules.filter((_, i) => !checks[i]).join(" · ")}
      </small>
    </label>
  );
}

