export function GlassLens({
  className,
  label = "Lens ×2",
  image = glassCover,
}: {
  className?: string;
  label?: string;
  image?: string;
}) {
  const lens = useRef<HTMLSpanElement>(null);
  const pos = useRef({ x: 0.58, y: 0.52 });
  const [zoomed, setZoomed] = useState(false);
  function position(
    x: number,
    y: number,
    w: number,
    h: number,
    zoom = zoomed ? 3 : 2,
  ) {
    const node = lens.current;
    if (!node) return;
    const radius = node.offsetWidth / 2;
    const px = Math.max(0, Math.min(w, x));
    const py = Math.max(0, Math.min(h, y));
    pos.current = { x: px / w, y: py / h };
    node.style.left = (100 * px) / w + "%";
    node.style.top = (100 * py) / h + "%";
    node.style.backgroundSize = w * zoom + "px " + h * zoom + "px";
    node.style.backgroundPosition =
      radius - zoom * px + "px " + (radius - zoom * py) + "px";
  }
  return (
    <div
      role="button"
      aria-pressed={zoomed}
      onClick={(e) => {
        setZoomed(!zoomed);
        const { clientWidth: w, clientHeight: h } = e.currentTarget;
        position(pos.current.x * w, pos.current.y * h, w, h, zoomed ? 2 : 3);
      }}
      tabIndex={0}
      aria-label="Magnifier: move with the pointer or arrow keys. Click to change the zoom."
      className={cn(
        "relative aspect-square w-[180px] touch-pan-y overflow-hidden rounded-2xl border border-white/20 bg-cover shadow-[0_12px_24px_-9px_#17372c80] outline-offset-4",
        className,
      )}
      style={{ backgroundImage: 'url("' + image + '")' }}
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        position(
          e.clientX - r.left,
          e.clientY - r.top,
          e.currentTarget.clientWidth,
          e.currentTarget.clientHeight,
        );
      }}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          e.currentTarget.click();
          return;
        }
        const keys: Record<string, [number, number]> = {
          ArrowLeft: [-1, 0],
          ArrowRight: [1, 0],
          ArrowUp: [0, -1],
          ArrowDown: [0, 1],
        };
        const delta = keys[e.key];
        if (!delta) return;
        e.preventDefault();
        const { clientWidth: w, clientHeight: h } = e.currentTarget;
        position(
          pos.current.x * w + delta[0] * 8,
          pos.current.y * h + delta[1] * 8,
          w,
          h,
        );
      }}
    >
      <span className="absolute top-2 left-2 flex items-center gap-1 rounded-full bg-black/70 px-2 py-1 text-[9px] font-medium text-white">
        <ScanSearch size={11} />
        {zoomed ? "Lens ×3" : label}
      </span>
      <span
        ref={lens}
        aria-hidden
        className="pointer-events-none absolute size-16 -translate-1/2 rounded-full border border-white/75 shadow-[inset_2px_3px_5px_#ffffff77,inset_-2px_-3px_5px_#0004,0_4px_10px_#0005]"
        style={{
          left: "58%",
          top: "52%",
          backgroundImage: 'url("' + image + '")',
          backgroundSize: "320px 320px",
          backgroundPosition: "-154px -134px",
        }}
      />
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { FileText, RefreshCw } from "lucide-react";
import { panel } from "@/lib/takt-surface";

export function PullRefresh({
  className,
  onRefresh,
}: {
  className?: string;
  onRefresh?: () => Promise<void>;
}) {
  const [count, setCount] = useState(0),
    [busy, setBusy] = useState(false),
    [error, setError] = useState(false);
  const [armed, setArmed] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const grip = useRef<{ id: number; y: number } | null>(null);
  const pending = useRef(false),
    suppress = useRef(false);
  function release() {
    grip.current = null;
    root.current?.removeAttribute("data-pulling");
    root.current?.style.removeProperty("--pull");
    setArmed(false);
  }
  async function refresh() {
    if (pending.current) return;
    pending.current = true;
    setBusy(true);
    setError(false);
    try {
      await onRefresh?.();
      setCount((n) => n + 1);
    } catch {
      setError(true);
    } finally {
      pending.current = false;
      setBusy(false);
    }
  }
  return (
    <div
      ref={root}
      className={cn(
        panel + " group grid w-64 max-w-full gap-2 overflow-hidden",
        className,
      )}
    >
      <button
        type="button"
        aria-label="Refresh"
        disabled={busy}
        className="grid w-full touch-pan-x gap-2 rounded-md py-1 text-left active:cursor-grabbing"
        onPointerDown={(e) => {
          if (!e.isPrimary || e.button !== 0) return;
          grip.current = { id: e.pointerId, y: e.clientY };
          root.current?.setAttribute("data-pulling", "");
          suppress.current = false;
          e.currentTarget.setPointerCapture(e.pointerId);
        }}
        onPointerMove={(e) => {
          const g = grip.current;
          if (!g || g.id !== e.pointerId) return;
          const dy = e.clientY - g.y;
          if (Math.abs(dy) > 4) suppress.current = true;
          setArmed(dy >= 88);
          root.current?.style.setProperty(
            "--pull",
            Math.max(0, Math.min(8, dy * 0.09)) + "px",
          );
        }}
        onPointerUp={(e) => {
          const g = grip.current;
          if (!g || g.id !== e.pointerId) return;
          const ready = e.clientY - g.y >= 88;
          release();
          if (ready) {
            suppress.current = true;
            void refresh();
          }
        }}
        onPointerCancel={() => {
          suppress.current = true;
          release();
        }}
        onLostPointerCapture={() => {
          if (grip.current) release();
        }}
        onClick={(e) => {
          if (e.detail === 0 || !suppress.current) void refresh();
          suppress.current = false;
        }}
      >
        <span className="flex items-center justify-between gap-2">
          <strong className="text-sm">Recent files</strong>
          <span
            className={
              "grid size-8 place-items-center rounded-full " +
              (armed ? "bg-primary text-primary-foreground" : "bg-muted")
            }
          >
            <RefreshCw
              size={14}
              className={busy ? "motion-safe:animate-spin" : ""}
            />
          </span>
        </span>
        <span className="flex items-center gap-2.5 border-y py-3 motion-safe:translate-y-[var(--pull,0px)] motion-safe:transition-transform motion-safe:duration-300 motion-safe:ease-out group-data-[pulling]:transition-none">
          <FileText size={18} className="text-muted-foreground" />
          <span className="grid gap-0.5">
            <b className="text-xs">Studio layout.fig</b>
            <span className="text-[11px] text-muted-foreground">
              {count ? "Synced" : "Local version"}
            </span>
          </span>
        </span>
      </button>
      <output className="text-[11px] text-muted-foreground">
        {error
          ? "Try again"
          : busy
            ? "Refreshing…"
            : armed
              ? "Release to refresh"
              : count
                ? "Version " + (count + 1)
                : "Pull down to sync"}
      </output>
    </div>
  );
}

