type Row = {
  id: string;
  label: string;
  to?: string;
  detail?: string;
  icon?: ReactNode;
  selected?: boolean;
  onSelect?: () => void;
};
export type StackPage = { title: string; rows?: Row[]; content?: ReactNode };
type Visit = { page: string; opener?: string };

export function StackPanel({
  className,
  title = "Library",
  items,
  renderPanel,
  pages,
  root = "home",
}: {
  className?: string;
  title?: string;
  items?: string[];
  renderPanel?: (name: string) => ReactNode;
  pages?: Record<string, StackPage>;
  root?: string;
}) {
  const [path, setPath] = useState<Visit[]>([]);
  const [view, setView] = useState("Covers");
  const [projectStatus, setProjectStatus] = useState<Record<string, string>>(
    {},
  );
  const custom = items !== undefined || !!renderPanel;
  const names = items ?? ["Projects", "Archive"];
  const projects = ["Glass collection", "Orbit collection"];
  const book: Record<string, StackPage> =
    pages ??
    (custom
      ? {
          [root]: {
            title,
            rows: names.map((label, i) => ({
              id: String(i),
              label,
              to: "item-" + i,
              icon: <Folder />,
            })),
          },
          ...Object.fromEntries(
            names.map((label, i) => [
              "item-" + i,
              {
                title: label,
                content: path.some((v) => v.page === "item-" + i)
                  ? (renderPanel?.(label) ?? "Section “" + label + "”")
                  : null,
              },
            ]),
          ),
        }
      : {
          [root]: {
            title,
            rows: [
              {
                id: "projects",
                label: "Projects",
                icon: <Folder />,
                detail: "2",
                to: "projects",
              },
              {
                id: "archive",
                label: "Archive",
                icon: <Archive />,
                to: "archive",
              },
              {
                id: "view",
                label: "Catalog view",
                icon: <PanelsTopLeft />,
                detail: view,
                to: "view",
              },
            ],
          },
          projects: {
            title: "Projects",
            rows: projects.map((label, i) => ({
              id: String(i),
              label,
              to: "project-" + i,
              icon: <Layers3 />,
              detail: projectStatus[i] ?? "In progress",
            })),
          },
          ...Object.fromEntries(
            projects.map((label, i) => [
              "project-" + i,
              {
                title: label,
                rows: ["In progress", "Under review", "Done"].map((status) => ({
                  id: status,
                  label: status,
                  selected: (projectStatus[i] ?? "In progress") === status,
                  onSelect: () =>
                    setProjectStatus((s) => ({ ...s, [i]: status })),
                })),
              },
            ]),
          ),
          archive: {
            title: "Archive",
            content: (
              <div className="grid justify-items-center gap-2 py-5 text-xs text-muted-foreground">
                <Archive size={22} />
                Archive is empty
              </div>
            ),
          },
          view: {
            title: "Catalog view",
            rows: ["Covers", "List"].map((label) => ({
              id: label,
              label,
              selected: view === label,
              onSelect: () => setView(label),
            })),
          },
        });
  const visits: Visit[] = [{ page: root }];
  for (const visit of path) {
    if (!book[visit.page]) break;
    visits.push(visit);
  }
  const top = visits[visits.length - 1],
    previous = visits.at(-2);
  const panel = useRef<HTMLElement>(null),
    body = useRef<HTMLDivElement>(null),
    heading = useRef<HTMLHeadingElement>(null),
    back = useRef<HTMLButtonElement>(null);
  const gesture = useRef<{
      id: number;
      x: number;
      y: number;
      time: number;
      dragging: boolean;
    } | null>(null),
    ignoreClick = useRef(false);
  const popping = useRef(false);
  const [height, setHeight] = useState<number | "auto">("auto");
  const x = useMotionValue(0),
    width = useMotionValue(288);
  const under = useTransform(() => (x.get() - width.get()) * 0.3);
  const reduced = useReducedMotion();
  const transition = reduced
    ? { duration: 0 }
    : { type: "spring" as const, duration: 0.42, bounce: 0 };
  useLayoutEffect(() => {
    const node = body.current,
      container = panel.current;
    if (!node || !container) return;
    const measure = () => {
      setHeight(node.offsetHeight);
      width.set(container.clientWidth);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    observer.observe(container);
    return () => observer.disconnect();
  }, [top.page, width]);
  function push(row: Row, label: HTMLElement) {
    if (popping.current) return;
    row.onSelect?.();
    if (!row.to || !book[row.to]) return;
    const origin = label.getBoundingClientRect();
    x.jump(reduced ? 0 : width.get());
    flushSync(() =>
      setPath([...visits.slice(1), { page: row.to!, opener: row.id }]),
    );
    const target = heading.current;
    if (target && !reduced) {
      const dest = target.getBoundingClientRect();
      target.animate(
        [
          {
            transform:
              "translate(" +
              (origin.left - dest.left) +
              "px," +
              (origin.top - dest.top) +
              "px)",
          },
          { transform: "translate(0,0)" },
        ],
        { duration: 410, easing: "cubic-bezier(.2,.8,.2,1)" },
      );
    }
    animate(x, 0, transition);
    back.current?.focus({ preventScroll: true });
  }
  async function pop() {
    if (!previous || popping.current) return;
    popping.current = true;
    if (!reduced)
      await animate(x, width.get(), {
        type: "spring",
        duration: 0.34,
        bounce: 0,
      });
    if (!panel.current) {
      x.jump(0);
      popping.current = false;
      return;
    }
    const restoreFocus = panel.current.contains(document.activeElement);
    flushSync(() => setPath(visits.slice(1, -1)));
    x.jump(0);
    popping.current = false;
    if (restoreFocus && top.opener)
      body.current
        ?.querySelector<HTMLElement>(
          '[data-entry="' + CSS.escape(top.opener) + '"]',
        )
        ?.focus({ preventScroll: true });
  }
  function content(page: StackPage) {
    return (
      <div className="grid gap-2 p-2">
        {!!page.rows?.length && (
          <div className="divide-y divide-border/65 overflow-clip rounded-xl bg-muted/65">
            {page.rows.map((row) => (
              <button
                key={row.id}
                type="button"
                data-entry={row.id}
                aria-pressed={row.selected}
                onClick={(e) =>
                  push(row, e.currentTarget.querySelector("[data-label]")!)
                }
                className="flex min-h-11 w-full items-center gap-2.5 px-3 text-left text-[13px] hover:bg-foreground/5 focus-visible:-outline-offset-2!"
              >
                {row.icon && (
                  <span
                    aria-hidden
                    className="grid size-7 shrink-0 place-items-center rounded-[8px] border bg-card text-card-foreground shadow-xs [&>svg]:size-3.5"
                  >
                    {row.icon}
                  </span>
                )}
                <span
                  data-label
                  className="pointer-events-none min-w-0 flex-1 truncate font-medium"
                >
                  {row.label}
                </span>
                {row.detail && (
                  <span className="pointer-events-none max-w-[35%] truncate text-xs text-muted-foreground">
                    {row.detail}
                  </span>
                )}
                {row.to ? (
                  <ChevronRight
                    size={13}
                    className="shrink-0 text-muted-foreground"
                  />
                ) : row.selected ? (
                  <Check size={15} />
                ) : null}
              </button>
            ))}
          </div>
        )}
        {page.content != null && (
          <div className="rounded-xl bg-muted/55 p-2 text-sm">
            {page.content}
          </div>
        )}
      </div>
    );
  }
  if (!book[top.page]) return null;
  return (
    <section
      ref={panel}
      className={cn(
        "relative w-[286px] max-w-full overflow-hidden rounded-[19px] border bg-card text-card-foreground shadow-[0_6px_20px_-12px_#0005]",
        className,
      )}
      onClickCapture={(e) => {
        if (ignoreClick.current && e.detail) {
          ignoreClick.current = false;
          e.preventDefault();
          e.stopPropagation();
        }
      }}
      onKeyDown={(e) => {
        if (e.key === "Escape" && previous) {
          e.preventDefault();
          void pop();
        }
      }}
    >
      <header className="relative z-10 flex h-11 items-center justify-center border-b border-border/65 bg-card px-10">
        {previous && (
          <button
            ref={back}
            type="button"
            aria-label="Back"
            onClick={() => void pop()}
            className="absolute left-2 grid size-8 place-items-center rounded-full hover:bg-muted"
          >
            <ChevronLeft size={17} />
          </button>
        )}
        <h3
          ref={heading}
          className="truncate text-sm font-semibold tracking-tight"
        >
          {book[top.page].title}
        </h3>
      </header>
      <motion.div
        initial={false}
        animate={{ height }}
        transition={transition}
        className="relative overflow-hidden"
        onPointerDown={(e) => {
          ignoreClick.current = false;
          if (
            !previous ||
            !e.isPrimary ||
            e.button !== 0 ||
            popping.current ||
            (e.target as Element).closest(
              "input,textarea,select,[contenteditable=true]",
            )
          )
            return;
          gesture.current = {
            id: e.pointerId,
            x: e.clientX,
            y: e.clientY,
            time: e.timeStamp,
            dragging: false,
          };
        }}
        onPointerMove={(e) => {
          const g = gesture.current;
          if (g?.id !== e.pointerId) return;
          const dx = e.clientX - g.x,
            dy = e.clientY - g.y;
          if (!g.dragging) {
            if (Math.max(Math.abs(dx), Math.abs(dy)) < 7) return;
            if (dx <= Math.abs(dy)) {
              gesture.current = null;
              return;
            }
            g.dragging = true;
            ignoreClick.current = true;
            e.currentTarget.setPointerCapture(e.pointerId);
          }
          x.set(Math.max(0, Math.min(width.get(), dx)));
        }}
        onPointerUp={(e) => {
          const g = gesture.current;
          if (g?.id !== e.pointerId) return;
          gesture.current = null;
          if (!g.dragging) return;
          const dx = e.clientX - g.x;
          if (
            dx > width.get() * 0.35 ||
            (dx > 16 && dx / Math.max(e.timeStamp - g.time, 1) > 0.5)
          )
            void pop();
          else animate(x, 0, transition);
        }}
        onPointerCancel={() => {
          if (gesture.current?.dragging) animate(x, 0, transition);
          gesture.current = null;
        }}
        style={{ touchAction: previous ? "pan-y pinch-zoom" : undefined }}
      >
        {previous && (
          <motion.div
            inert
            aria-hidden
            className="absolute inset-x-0 top-0 opacity-65"
            style={{ x: under }}
          >
            {content(book[previous.page])}
          </motion.div>
        )}
        <motion.div
          ref={body}
          style={{ x, touchAction: previous ? "pan-y pinch-zoom" : undefined }}
          className="relative max-h-44 overflow-y-auto bg-card"
        >
          {content(book[top.page])}
        </motion.div>
      </motion.div>
    </section>
  );
}

"use client";
import { cn } from "@/lib/utils";

import { useState, useRef, useEffect } from "react";
import { Play, Pause, Repeat2, Volume2, VolumeX } from "lucide-react";
import { foldCover } from "@/lib/takt-art-fold";

// A short, local four-note sample for previews without an audio source.
function makeSample() {
  const rate = 11025,
    samples = rate * 8;
  const buffer = new ArrayBuffer(44 + samples * 2);
  const view = new DataView(buffer);
  function tag(offset: number, text: string) {
    for (let i = 0; i < text.length; i++)
      view.setUint8(offset + i, text.charCodeAt(i));
  }
  tag(0, "RIFF");
  view.setUint32(4, 36 + samples * 2, true);
  tag(8, "WAVE");
  tag(12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, rate, true);
  view.setUint32(28, rate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  tag(36, "data");
  view.setUint32(40, samples * 2, true);
  const notes = [220, 277.18, 329.63, 440];
  for (let i = 0; i < samples; i++) {
    const t = i / rate,
      beat = t % 0.5,
      note = notes[Math.floor(t * 2) % notes.length];
    const envelope = Math.min(1, beat * 80) * Math.exp(-beat * 10);
    view.setInt16(
      44 + i * 2,
      Math.sin(2 * Math.PI * note * beat) * envelope * 4400,
      true,
    );
  }
  return URL.createObjectURL(new Blob([buffer], { type: "audio/wav" }));
}
export function GlassPlayer({
  className,
  title = "Study",
  cover = foldCover,
  src,
}: {
  className?: string;
  title?: string;
  src?: string;
  cover?: string;
}) {
  const [playing, setPlaying] = useState(false);
  const [error, setError] = useState("");
  const audio = useRef<HTMLAudioElement>(null);
  const sample = useRef("");
  useEffect(() => {
    const player = audio.current;
    return () => {
      player?.pause();
      if (sample.current) {
        URL.revokeObjectURL(sample.current);
        sample.current = "";
      }
    };
  }, []);
  const [time, setTime] = useState(0);
  const [duration, setDuration] = useState(src ? 0 : 8);
  const [loop, setLoop] = useState(false);
  const [muted, setMuted] = useState(false);
  const stamp = (v: number) =>
    Math.floor(v / 60) + ":" + String(Math.floor(v) % 60).padStart(2, "0");
  function prepare(player: HTMLAudioElement) {
    if (src) return;
    if (!sample.current) sample.current = makeSample();
    if (player.src !== sample.current) player.src = sample.current;
  }
  async function toggle() {
    const player = audio.current;
    if (!player) return;
    if (!player.paused) {
      player.pause();
      return;
    }
    try {
      prepare(player);
      await player.play();
      setError("");
    } catch (reason) {
      if (!(reason instanceof DOMException && reason.name === "AbortError"))
        setError("Audio unavailable");
    }
  }
  return (
    <section
      className={cn(
        "grid w-[278px] max-w-full gap-3 rounded-2xl border border-foreground/15 bg-card p-4 text-card-foreground shadow-sm",
        className,
      )}
    >
      <div className="flex items-center gap-3.5">
        <span
          role="img"
          aria-label="Track artwork"
          className="size-16 shrink-0 rounded-lg bg-cover bg-center"
          style={{ backgroundImage: "url(" + JSON.stringify(cover) + ")" }}
        />
        <span className="min-w-0 flex-1">
          <strong className="block truncate text-lg font-semibold tracking-tight">
            {title}
          </strong>
          <span role="status" className="text-xs text-muted-foreground">
            {error || (playing ? "Playing" : "Paused")}
          </span>
        </span>
        <button
          type="button"
          aria-label={playing ? "Pause" : "Play"}
          onClick={toggle}
          className="grid size-10 shrink-0 place-items-center rounded-full bg-primary text-primary-foreground motion-safe:active:scale-95"
        >
          {playing ? (
            <Pause size={16} fill="currentColor" />
          ) : (
            <Play size={16} fill="currentColor" className="ml-0.5" />
          )}
        </button>
      </div>
      <div>
        <label className="relative flex h-6 cursor-pointer items-center rounded-md has-[:focus-visible]:ring-1 has-[:focus-visible]:ring-foreground/45">
          <span
            aria-hidden
            className="relative mx-1 h-1 w-full rounded-full bg-foreground/15"
          >
            <i
              className="absolute inset-y-0 left-0 rounded-full bg-primary"
              style={{ width: (duration ? (100 * time) / duration : 0) + "%" }}
            />
            <i
              className="absolute top-1/2 size-2.5 -translate-1/2 rounded-full bg-primary"
              style={{ left: (duration ? (100 * time) / duration : 0) + "%" }}
            />
          </span>
          <input
            aria-label="Playback position"
            type="range"
            min={0}
            max={duration || 1}
            step={0.01}
            value={Math.min(time, duration)}
            disabled={!duration}
            onChange={(e) => {
              if (audio.current && duration) {
                prepare(audio.current);
                audio.current.currentTime = +e.target.value;
                setTime(+e.target.value);
              }
            }}
            className="absolute inset-0 size-full cursor-pointer opacity-0"
          />
        </label>
        <div className="flex items-center gap-1">
          <span className="mr-auto font-mono text-[10px] tabular-nums text-muted-foreground">
            {stamp(time)} / {stamp(duration)}
          </span>
          <button
            aria-label="Repeat track"
            aria-pressed={loop}
            type="button"
            onClick={() => setLoop(!loop)}
            className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-muted aria-pressed:bg-muted aria-pressed:text-foreground"
          >
            <Repeat2 size={15} />
          </button>
          <button
            aria-label="Mute"
            aria-pressed={muted}
            type="button"
            onClick={() => setMuted(!muted)}
            className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-muted aria-pressed:bg-muted aria-pressed:text-foreground"
          >
            {muted ? <VolumeX size={15} /> : <Volume2 size={15} />}
          </button>
        </div>
      </div>
      <audio
        ref={audio}
        src={src}
        muted={muted}
        loop={loop}
        preload={src ? "metadata" : "none"}
        onError={() => {
          setPlaying(false);
          setDuration(0);
          setTime(0);
          setError("Audio unavailable");
        }}
        onEmptied={() => {
          setPlaying(false);
          setTime(0);
          setDuration(src ? 0 : 8);
          setError("");
        }}
        onLoadedMetadata={(e) =>
          setDuration(
            Number.isFinite(e.currentTarget.duration)
              ? e.currentTarget.duration
              : 0,
          )
        }
        onTimeUpdate={(e) => setTime(e.currentTarget.currentTime)}
        onPlay={() => {
          setPlaying(true);
          setError("");
        }}
        onPause={() => setPlaying(false)}
        onEnded={() => setPlaying(false)}
      />
    </section>
  );
}

"use client";
import { cn } from "@/lib/utils";

import { useState } from "react";

export function WeightWave({
  className,
  text = "Amplitude",
}: {
  className?: string;
  text?: string;
}) {
  const [index, setIndex] = useState(-1);
  const letters = Array.from(text);
  if (!letters.length) return null;
  return (
    <button
      type="button"
      aria-label={text}
      className={cn(
        "cursor-pointer whitespace-pre-wrap text-4xl tracking-[-.055em]",
        className,
      )}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
          e.preventDefault();
          setIndex(
            ((index < 0 && e.key === "ArrowLeft" ? 0 : index) +
              (e.key === "ArrowRight" ? 1 : -1) +
              letters.length) %
              letters.length,
          );
        }
      }}
      onBlur={() => setIndex(-1)}
      onPointerLeave={() => setIndex(-1)}
      onClick={() => setIndex((index + 1) % letters.length)}
    >
      {letters.map((v, i) => (
        <span
          key={i}
          aria-hidden
          onPointerEnter={() => setIndex(i)}
          className="inline-block motion-safe:transition-[font-weight,translate] duration-350 ease-out motion-reduce:translate-none!"
          style={{
            fontWeight:
              index < 0
                ? 450
                : 350 + 550 * Math.exp(-Math.pow((i - index) / 1.65, 2)),
            translate:
              index < 0
                ? "none"
                : "0 " + -Math.max(0, 4 - Math.abs(i - index) * 2) + "px",
          }}
        >
          {v}
        </span>
      ))}
    </button>
  );
}

