"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { ArrowUp, Check, LoaderCircle, Undo2 } from "lucide-react";
import { panel } from "@/lib/takt-surface";
export function PromptBox({
  className,
  onSend,
  suggestions = ["Find an idea", "Refine the task"],
}: {
  className?: string;
  suggestions?: string[];
  onSend?: (text: string) => void | Promise<void>;
}) {
  const [text, setText] = useState("");
  const [last, setLast] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(false);
  const field = useRef<HTMLTextAreaElement>(null);
  const pending = useRef(false);
  async function send() {
    const message = text.trim();
    if (!message || pending.current) return;
    pending.current = true;
    setBusy(true);
    setError(false);
    try {
      await onSend?.(message);
      setLast(message);
      setText("");
    } catch {
      setError(true);
    } finally {
      pending.current = false;
      setBusy(false);
    }
  }
  return (
    <form
      className={cn(panel + " grid w-72 max-w-full gap-2", className)}
      onSubmit={(e) => {
        e.preventDefault();
        void send();
      }}
    >
      {last && (
        <div className="flex items-center gap-1.5 rounded-lg bg-muted px-2 py-1.5 text-xs motion-safe:animate-in motion-safe:slide-in-from-bottom-1">
          <Check size={13} />
          <output className="min-w-0 flex-1 truncate">{last}</output>
          <button
            type="button"
            aria-label="Edit previous prompt"
            disabled={busy}
            onClick={() => {
              setText(last);
              setLast("");
              field.current?.focus();
            }}
          >
            <Undo2 size={14} />
          </button>
        </div>
      )}
      {!text && !last && suggestions.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {suggestions.map((v) => (
            <button
              type="button"
              className="rounded-md border bg-muted px-2.5 py-1.5 text-[11px] hover:bg-background"
              key={v}
              onClick={() => {
                setText(v);
                field.current?.focus();
              }}
            >
              {v}
            </button>
          ))}
        </div>
      )}
      <textarea
        ref={field}
        rows={2}
        aria-label="Prompt"
        readOnly={busy}
        placeholder="What would you like to ask?"
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          setError(false);
        }}
        onKeyDown={(e) => {
          if (e.nativeEvent.isComposing || e.keyCode === 229) return;
          if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
            e.preventDefault();
            void send();
          }
        }}
        className="min-w-0 resize-none rounded-md bg-transparent px-1 text-sm leading-relaxed outline-offset-2"
      />
      <div className="flex items-center justify-between border-t pt-2">
        <small role="status" className="text-[10px] text-muted-foreground">
          {error ? "Could not send" : "Shift + Enter · new line"}
        </small>
        <button
          type="submit"
          aria-label="Send"
          disabled={busy || !text.trim()}
          className="grid size-8 place-items-center rounded-full bg-primary text-primary-foreground motion-safe:transition-transform motion-safe:active:scale-90 disabled:opacity-35"
        >
          {busy ? (
            <LoaderCircle className="motion-safe:animate-spin" size={15} />
          ) : (
            <ArrowUp size={16} />
          )}
        </button>
      </div>
    </form>
  );
}

"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
} from "@/lib/takt-surface";

import { useState, useEffect } from "react";
import { useReducedMotion } from "motion/react";

export function StreamingReply({
  className,
  text = "Rhythm, contrast and motion give an interface its shape.",
}: {
  className?: string;
  text?: string;
}) {
  const [revealed, setCount] = useState(0);
  const [running, setRunning] = useState(false);
  const words = text.trim() ? text.trim().split(/\s+/) : [];
  const count = Math.min(revealed, words.length);
  const reduced = useReducedMotion();
  useEffect(() => {
    if (!running || count >= words.length) return;
    const id = setTimeout(() => setCount((i) => i + 1), 85);
    return () => clearTimeout(id);
  }, [running, count, words.length]);
  return (
    <div className={cn(surfacePanel + " grid w-56 gap-2", className)}>
      <p className="min-h-16 rounded-lg bg-muted px-3 py-2.5 text-sm leading-relaxed">
        {count
          ? words.slice(0, count).map((word, i) => (
              <span
                key={i}
                className="inline-block whitespace-pre motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-bottom-1"
              >
                {word}{" "}
              </span>
            ))
          : "Reply preview"}
        {running && count < words.length && (
          <i
            aria-hidden
            className="inline-block size-1.5 rounded-full bg-primary motion-safe:animate-pulse"
          />
        )}
      </p>
      <progress
        aria-label="Reply progress"
        max={Math.max(1, words.length)}
        value={count}
        className="h-1 w-full overflow-hidden rounded-full accent-primary"
      />
      <button
        type="button"
        className={surfaceSecondary}
        disabled={!words.length}
        onClick={() => {
          if (running && count < words.length) {
            setRunning(false);
            return;
          }
          if (count === words.length) setCount(0);
          if (reduced) setCount(words.length);
          setRunning(true);
        }}
      >
        {running && count < words.length
          ? "Pause"
          : count === words.length
            ? "Retry"
            : count
              ? "Resume"
              : "Show reply"}
      </button>
    </div>
  );
}

"use client";
import { cn } from "@/lib/utils";
import {
  panel as surfacePanel,
  secondary as surfaceSecondary,
} from "@/lib/takt-surface";

import { useState } from "react";

export function GhostSuggestion({
  className,
  options = ["Build a catalog", "Create a layout", "Open a file"],
  onChange,
}: {
  className?: string;
  options?: string[];
  onChange?: (value: string) => void;
}) {
  const [value, setValue] = useState("");
  const [dismissed, setDismissed] = useState(false);
  const [atEnd, setAtEnd] = useState(true);
  const match =
    !dismissed &&
    atEnd &&
    value.length > 0 &&
    options.find(
      (x) =>
        x.toLowerCase().startsWith(value.toLowerCase()) &&
        x.toLowerCase() !== value.toLowerCase(),
    );
  function update(v: string) {
    setValue(v);
    setDismissed(false);
    onChange?.(v);
  }
  return (
    <div
      className={cn(surfacePanel + " grid w-64 max-w-full gap-2", className)}
    >
      <label className="relative flex min-h-11 items-center rounded-lg border border-foreground/15 bg-background px-3 text-sm focus-within:border-foreground/50">
        <span
          aria-hidden
          className="pointer-events-none absolute inset-x-3 overflow-hidden whitespace-pre text-muted-foreground"
        >
          <span className="invisible">{value}</span>
          {match ? match.slice(value.length) : ""}
        </span>
        <input
          aria-label="Autocomplete"
          spellCheck={false}
          autoComplete="off"
          placeholder="Start typing…"
          onSelect={(e) => {
            const n = e.currentTarget;
            setAtEnd(
              n.selectionStart === n.value.length &&
                n.selectionEnd === n.value.length &&
                n.scrollLeft === 0,
            );
          }}
          className="relative w-full min-w-0 bg-transparent caret-foreground outline-none! selection:bg-primary/20"
          value={value}
          onChange={(e) => update(e.target.value)}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing || e.keyCode === 229) return;

            if (e.key === "Escape") {
              setDismissed(true);
              return;
            }
            if (
              (e.key === "ArrowRight" ||
                (e.key === "Tab" && !e.shiftKey && value.length > 0)) &&
              match &&
              e.currentTarget.selectionStart === value.length
            ) {
              e.preventDefault();
              update(match);
            }
          }}
        />
      </label>
      <button
        type="button"
        className={surfaceSecondary}
        disabled={!match}
        onClick={() => match && update(match)}
      >
        Accept{" "}
        <kbd className="ml-1 rounded border bg-muted px-1 font-mono text-[9px]">
          Tab
        </kbd>
      </button>
    </div>
  );
}

"use client";

import { useEffect, useId, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
