"use client";
import { cn } from "@/lib/utils";

import { useState, useRef, useEffect } from "react";
import { LoaderCircle, Mic, Pause, Play, Square } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";

const displayTime = (time: number) =>
  Math.floor(time / 60) + ":" + String(Math.floor(time) % 60).padStart(2, "0");

export function VoiceInput({
  className,
  onRecord,
}: {
  className?: string;
  onRecord?: (blob: Blob) => void;
}) {
  const reduced = useReducedMotion();
  const [playing, setPlaying] = useState(false);
  const [position, setPosition] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playError, setPlayError] = useState(false);
  const requesting = useRef(false);
  const recorder = useRef<MediaRecorder | null>(null);
  const session = useRef({ active: false });
  const [recording, setRecording] = useState<Blob | null>(null);
  const [status, setStatus] = useState("idle");
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    if (status !== "recording") return;
    const started = Date.now();
    const timer = setInterval(
      () => setSeconds(Math.floor((Date.now() - started) / 1000)),
      1000,
    );
    return () => clearInterval(timer);
  }, [status]);
  const wave = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const stream = recorder.current?.stream,
      canvas = wave.current;
    if (
      status !== "recording" ||
      !stream ||
      !canvas ||
      reduced ||
      typeof AudioContext === "undefined"
    )
      return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    let audio: AudioContext;
    try {
      audio = new AudioContext();
    } catch {
      return;
    }
    const meter = audio.createAnalyser(),
      source = audio.createMediaStreamSource(stream);
    meter.fftSize = 512;
    source.connect(meter);
    void audio.resume().catch(() => {});
    const samples = new Uint8Array(meter.fftSize);
    const levels = new Float32Array(36);
    const width = 144,
      height = 32,
      ratio = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = width * ratio;
    canvas.height = height * ratio;
    ctx.scale(ratio, ratio);
    const ink = getComputedStyle(canvas).color;
    let frame = 0,
      last = 0,
      envelope = 0;
    function draw(now: number) {
      if (now - last >= 42 && ctx && canvas) {
        last = now;
        meter.getByteTimeDomainData(samples);
        let energy = 0;
        for (const sample of samples) energy += ((sample - 128) / 128) ** 2;
        const level = Math.min(1, 4 * Math.sqrt(energy / samples.length));
        envelope += (level - envelope) * (level > envelope ? 0.8 : 0.35);
        levels.copyWithin(0, 1);
        levels[levels.length - 1] = envelope;
        ctx.clearRect(0, 0, width, height);
        ctx.strokeStyle = ink;
        ctx.lineWidth = 2.4;
        ctx.lineCap = "round";
        for (let i = 0; i < levels.length; i++) {
          const x = 2 + i * 4,
            h = 0.35 + levels[i] * 13.5;
          ctx.globalAlpha = 0.26 + (0.74 * i) / (levels.length - 1);
          ctx.beginPath();
          ctx.moveTo(x, height / 2 - h);
          ctx.lineTo(x, height / 2 + h);
          ctx.stroke();
        }
        canvas.parentElement?.style.setProperty(
          "--voice-level",
          String(envelope),
        );
      }
      frame = requestAnimationFrame(draw);
    }
    function visibility() {
      cancelAnimationFrame(frame);
      if (!document.hidden) frame = requestAnimationFrame(draw);
    }
    visibility();
    document.addEventListener("visibilitychange", visibility);
    const track = canvas.parentElement;
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("visibilitychange", visibility);
      track?.style.removeProperty("--voice-level");
      source.disconnect();
      meter.disconnect();
      void audio.close().catch(() => {});
    };
  }, [status, reduced]);
  const playback = useRef<HTMLAudioElement>(null);
  useEffect(() => {
    const generation = { active: true };
    session.current = generation;
    return () => {
      generation.active = false;
      requesting.current = false;
      const r = recorder.current;
      if (r && r.state !== "inactive") r.stop();
      r?.stream.getTracks().forEach((t) => t.stop());
      recorder.current = null;
      setStatus("idle");
    };
  }, []);
  useEffect(() => {
    if (!recording) return;
    const objectUrl = URL.createObjectURL(recording);
    if (playback.current) playback.current.src = objectUrl;
    return () => URL.revokeObjectURL(objectUrl);
  }, [recording]);
  async function record() {
    const generation = session.current;
    if (requesting.current || status === "waiting" || status === "stopping")
      return;
    if (recorder.current?.state === "recording") {
      setStatus("stopping");
      recorder.current.stop();
      return;
    }
    requesting.current = true;
    setStatus("waiting");
    let stream: MediaStream | undefined;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      if (!generation.active) {
        stream.getTracks().forEach((t) => t.stop());
        return;
      }
      const r = new MediaRecorder(stream);
      recorder.current = r;
      const started = performance.now();
      const chunks: Blob[] = [];
      r.ondataavailable = (e) => {
        if (e.data.size) chunks.push(e.data);
      };
      r.onstop = () => {
        r.stream.getTracks().forEach((t) => t.stop());
        if (!generation.active || recorder.current !== r) return;
        recorder.current = null;
        const blob = new Blob(chunks, { type: r.mimeType });
        setDuration(Math.max(0.01, (performance.now() - started) / 1000));
        setPosition(0);
        setPlayError(false);
        setRecording(blob);
        setStatus("idle");
        onRecord?.(blob);
      };
      r.onerror = () => {
        r.stream.getTracks().forEach((t) => t.stop());
        if (!generation.active || recorder.current !== r) return;
        recorder.current = null;
        setStatus("error");
      };
      playback.current?.pause();
      setPlaying(false);
      setSeconds(0);
      r.start();
      setStatus("recording");
    } catch {
      stream?.getTracks().forEach((t) => t.stop());
      if (generation.active) {
        recorder.current = null;
        setStatus("error");
      }
    } finally {
      if (generation.active) requesting.current = false;
    }
  }
  const capturing = status === "recording";
  const busy = status === "waiting" || status === "stopping";
  const ready = !!recording && !capturing && !busy;
  async function togglePlayback() {
    const player = playback.current;
    if (!player) return;
    if (!player.paused) {
      player.pause();
      return;
    }
    try {
      setPlayError(false);
      await player.play();
    } catch {
      setPlayError(true);
    }
  }
  return (
    <section
      className={cn(
        "w-[266px] max-w-full rounded-[19px] border bg-card p-3.5 text-card-foreground shadow-sm",
        className,
      )}
    >
      <div className="mb-2.5 flex items-center justify-between gap-2">
        <span className="text-xs font-semibold">
          {capturing
            ? "Recording"
            : ready
              ? "Voice recording"
              : "Voice note"}
        </span>
        <span
          aria-label="Recording time"
          className="font-mono text-[11px] text-muted-foreground tabular-nums"
        >
          {displayTime(
            capturing
              ? seconds
              : ready
                ? playing || position > 0
                  ? position
                  : duration
                : 0,
          )}
        </span>
      </div>
      <div className="relative flex h-[54px] items-center gap-3 overflow-hidden rounded-[13px] bg-neutral-900 px-2.5 text-white dark:bg-neutral-950">
        <button
          type="button"
          aria-label={capturing ? "Stop recording" : "Record voice"}
          disabled={busy}
          onClick={record}
          className="relative isolate grid size-9 shrink-0 place-items-center rounded-full bg-[#d8eee0] text-[#153526] disabled:opacity-70"
        >
          {capturing && !reduced && (
            <i
              aria-hidden
              className="absolute -inset-1 -z-10 rounded-full border border-emerald-300/55"
              style={{
                transform: "scale(calc(1 + var(--voice-level,0) * .35))",
              }}
            />
          )}
          <motion.span
            key={status}
            initial={reduced ? false : { scale: 0.72, opacity: 0.5 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ type: "spring", stiffness: 460, damping: 25 }}
          >
            {busy ? (
              <LoaderCircle size={16} className="motion-safe:animate-spin" />
            ) : capturing ? (
              <Square size={13} fill="currentColor" />
            ) : (
              <Mic size={16} />
            )}
          </motion.span>
        </button>
        <canvas
          aria-hidden
          ref={wave}
          width={144}
          height={32}
          className={cn(
            "h-8 min-w-0 flex-1 text-emerald-300",
            !capturing || reduced ? "hidden" : "block",
          )}
        />
        {(!capturing || reduced) && (
          <span
            aria-hidden
            className="flex h-8 flex-1 items-center justify-between gap-0.5"
          >
            {Array.from({ length: 30 }, (_, i) => (
              <i
                key={i}
                className="w-0.5 rounded-full bg-emerald-100/50"
                style={{ height: capturing ? 4 : 2 }}
              />
            ))}
          </span>
        )}
      </div>
      <div className="mt-2 flex min-h-5 items-center gap-2 text-[11px] text-muted-foreground">
        {status === "error" ? (
          <span role="status">Microphone unavailable</span>
        ) : busy ? (
          <span role="status">
            {status === "waiting"
              ? "Requesting microphone…"
              : "Saving recording…"}
          </span>
        ) : capturing ? (
          <>
            <i aria-hidden className="size-1.5 rounded-full bg-red-500" />
            Tap the square to finish
          </>
        ) : ready ? (
          <>
            <button
              type="button"
              aria-label={
                playing ? "Pause recording" : "Play recording"
              }
              onClick={togglePlayback}
              className="grid size-7 place-items-center rounded-full bg-muted text-foreground"
            >
              {playing ? <Pause size={13} /> : <Play size={13} />}
            </button>
            <input
              type="range"
              aria-label="Recording position"
              className="min-w-0 flex-1 accent-emerald-700"
              min={0}
              max={duration}
              step={0.01}
              value={Math.min(position, duration)}
              onChange={(e) => {
                const t = e.currentTarget.valueAsNumber;
                if (playback.current) {
                  playback.current.currentTime = t;
                  setPosition(t);
                }
              }}
            />
            {playError && <span role="status">Playback error</span>}
          </>
        ) : (
          <span>Tap the microphone to record</span>
        )}
      </div>
      {recording && (
        <audio
          ref={playback}
          hidden
          onPlay={() => setPlaying(true)}
          onPause={() => setPlaying(false)}
          onEnded={() => {
            setPlaying(false);
            setPosition(0);
          }}
          onTimeUpdate={(e) => setPosition(e.currentTarget.currentTime)}
          onDurationChange={(e) => {
            const d = e.currentTarget.duration;
            if (Number.isFinite(d) && d > 0) setDuration(d);
          }}
        />
      )}
    </section>
  );
}

"use client";
import { cn } from "@/lib/utils";

import { useCallback, useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { Check, Upload } from "lucide-react";

export function HoldToPublish({
  className,
  duration = 1200,
  label = "Publish",
  onPublish,
}: {
  className?: string;
  duration?: number;
  label?: string;
  onPublish?: () => void;
}) {
  const [phase, setPhase] = useState<"idle" | "holding" | "published">("idle");
  const timeout = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const phaseRef = useRef(phase);
  const reduced = useReducedMotion();
  const holdMs = Number.isFinite(duration) ? Math.max(0, duration) : 1200;

  const change = useCallback((next: typeof phase) => {
    phaseRef.current = next;
    setPhase(next);
  }, []);
  const cancel = useCallback(() => {
    if (phaseRef.current !== "holding") return;
    clearTimeout(timeout.current);
    change("idle");
  }, [change]);
  useEffect(() => {
    function visibility() {
      if (document.hidden) cancel();
    }
    window.addEventListener("blur", cancel);
    document.addEventListener("visibilitychange", visibility);
    return () => {
      window.removeEventListener("blur", cancel);
      document.removeEventListener("visibilitychange", visibility);
      clearTimeout(timeout.current);
      phaseRef.current = "idle";
      setPhase("idle");
    };
  }, [cancel]);
  function begin() {
    if (phaseRef.current !== "idle") return;
    change("holding");
    timeout.current = setTimeout(() => {
      change("published");
      timeout.current = setTimeout(() => change("idle"), 1700);
      onPublish?.();
    }, holdMs);
  }
  const published = phase === "published";
  return (
    <motion.button
      type="button"
      initial={false}
      aria-label={
        published
          ? "Published"
          : label === "Publish"
            ? "Hold to publish"
            : "Hold to run “" + label + "”"
      }
      animate={{
        width: published ? 56 : 220,
        scale: phase === "holding" && !reduced ? 0.97 : 1,
      }}
      transition={
        reduced
          ? { duration: 0 }
          : { type: "spring", stiffness: 240, damping: 27 }
      }
      className={cn(
        "relative grid h-14 max-w-full touch-none place-items-center overflow-hidden rounded-full border border-foreground/10 bg-card font-medium text-card-foreground shadow-md select-none",
        published && "bg-primary",
        className,
      )}
      onPointerDown={(e) => {
        if (e.isPrimary && e.button === 0) {
          e.currentTarget.setPointerCapture(e.pointerId);
          begin();
        }
      }}
      onPointerCancel={cancel}
      onLostPointerCapture={cancel}
      onPointerUp={cancel}
      onBlur={cancel}
      onContextMenu={(e) => e.preventDefault()}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          if (!e.repeat) begin();
        }
      }}
      onKeyUp={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          cancel();
        }
      }}
    >
      {published ? (
        <Check
          aria-hidden
          size={21}
          className="relative text-primary-foreground"
        />
      ) : (
        <>
          <span
            aria-hidden
            className="absolute flex items-center gap-2 whitespace-nowrap"
          >
            <Upload size={16} />
            {label}
          </span>
          <span
            aria-hidden
            className="absolute inset-0 flex items-center justify-center gap-2 whitespace-nowrap bg-primary text-primary-foreground motion-safe:transition-[clip-path] motion-reduce:duration-0! motion-reduce:transition-none!"
            style={{
              clipPath: phase === "holding" ? "inset(0)" : "inset(0 100% 0 0)",
              transitionDuration: (phase === "holding" ? holdMs : 180) + "ms",
              transitionTimingFunction: "linear",
            }}
          >
            <Upload size={16} />
            {label}
          </span>
        </>
      )}
      <span className="sr-only" role="status">
        {published ? "Published" : ""}
      </span>
    </motion.button>
  );
}

"use client";
import { cn } from "@/lib/utils";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { ArrowRight, Search } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";

const subscribePlatform = () => () => {};
const platformKey = () =>
  /Mac|iPhone|iPad|iPod/i.test(navigator.platform) ? "⌘" : "Ctrl";
const defaultKey = () => "Ctrl";

export function CommandSearch({
  className,
  label = "Search",
  placeholder = "Search project",
  onSearch,
  shortcut = true,
}: {
  className?: string;
  label?: string;
  placeholder?: string;
  onSearch?: (query: string) => void;
  shortcut?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [lastQuery, setLastQuery] = useState("");
  const trigger = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  const input = useRef<HTMLInputElement>(null);
  const root = useRef<HTMLFormElement>(null);
  const modifier = useSyncExternalStore(
    subscribePlatform,
    platformKey,
    defaultKey,
  );
  const reduced = useReducedMotion();

  useEffect(() => {
    if (!shortcut) return;
    function handleShortcut(event: KeyboardEvent) {
      if (
        event.defaultPrevented ||
        event.repeat ||
        event.isComposing ||
        event.altKey ||
        event.shiftKey ||
        !(event.ctrlKey || event.metaKey) ||
        event.code !== "KeyK"
      )
        return;
      // Leave keyboard ownership with a modal or another editable field.
      if (
        event.target instanceof Element &&
        event.target.closest(
          "input,textarea,select,[contenteditable=true],dialog[open],[role=dialog]",
        )
      )
        return;
      event.preventDefault();
      setOpen(true);
    }
    window.addEventListener("keydown", handleShortcut);
    return () => window.removeEventListener("keydown", handleShortcut);
  }, [shortcut]);

  useEffect(() => {
    if (!open) {
      if (restoreFocus.current) {
        restoreFocus.current = false;
        trigger.current?.focus({ preventScroll: true });
      }
      return;
    }
    input.current?.focus({ preventScroll: true });
    function outside(event: PointerEvent) {
      if (event.target instanceof Node && !root.current?.contains(event.target))
        setOpen(false);
    }
    document.addEventListener("pointerdown", outside);
    return () => document.removeEventListener("pointerdown", outside);
  }, [open]);

  function closeAndFocus() {
    restoreFocus.current = true;
    setOpen(false);
  }

  return (
    <motion.form
      ref={root}
      role="search"
      aria-keyshortcuts={shortcut ? "Meta+K Control+K" : undefined}
      initial={false}
      animate={{ width: open ? 264 : 192 }}
      transition={
        reduced
          ? { duration: 0 }
          : { type: "spring", stiffness: 400, damping: 32 }
      }
      className={cn(
        "relative flex h-12 max-w-full items-center overflow-hidden rounded-xl border border-foreground/10 bg-card text-sm text-card-foreground shadow-sm focus-within:ring-1 focus-within:ring-foreground/35",
        className,
      )}
      onKeyDown={(event) => {
        if (event.key === "Escape" && open) {
          event.preventDefault();
          closeAndFocus();
        }
      }}
      onBlur={(event) => {
        if (
          event.relatedTarget &&
          !event.currentTarget.contains(event.relatedTarget)
        )
          setOpen(false);
      }}
      onSubmit={(event) => {
        event.preventDefault();
        const value = query.trim();
        if (!value) return;
        onSearch?.(value);
        setLastQuery(value);
        setQuery("");
        closeAndFocus();
      }}
    >
      <button
        ref={trigger}
        type="button"
        aria-expanded={open}
        inert={open}
        aria-label={label}
        tabIndex={open ? -1 : 0}
        className={
          "absolute inset-0 flex items-center gap-2.5 rounded-[inherit] px-3.5 text-left focus:outline-none! " +
          (open ? "pointer-events-none opacity-0" : "")
        }
        onClick={() => setOpen(true)}
      >
        <Search size={16} className="shrink-0" />
        <span className="min-w-0 flex-1 truncate">{lastQuery || label}</span>
        {shortcut && (
          <kbd
            aria-hidden
            className="shrink-0 rounded-md border bg-muted px-1.5 py-0.5 font-mono text-[10px]"
          >
            {modifier} K
          </kbd>
        )}
      </button>
      {open && (
        <div className="relative flex w-full items-center gap-2 bg-card px-3 motion-safe:animate-in motion-safe:fade-in">
          <Search size={16} className="shrink-0" />
          <input
            ref={input}
            aria-label={placeholder}
            onKeyDown={(e) => {
              if (e.key === "ArrowUp" && !query && lastQuery) {
                e.preventDefault();
                setQuery(lastQuery);
              }
            }}
            value={query}
            placeholder={placeholder}
            className="min-w-0 flex-1 bg-transparent focus:outline-none!"
            onChange={(e) => setQuery(e.target.value)}
          />
          <button
            type="submit"
            aria-label="Search"
            disabled={!query.trim()}
            className="grid size-8 place-items-center rounded-lg bg-primary text-primary-foreground disabled:opacity-40"
          >
            <ArrowRight size={15} />
          </button>
        </div>
      )}
    </motion.form>
  );
}

"use client";
import { cn } from "@/lib/utils";

import {
  useId,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";

type SwipeTab = { id: string; title: string; content: ReactNode };
const defaults: SwipeTab[] = [
  {
    id: "overview",
    title: "Overview",
    content: (
      <>
        <span className="text-xs text-muted-foreground">Views today</span>
        <strong className="block text-3xl tracking-tight">1 284</strong>
      </>
    ),
  },
  {
    id: "activity",
    title: "Activity",
    content: (
      <>
        <span className="text-xs text-muted-foreground">
          Last change
        </span>
        <strong className="block text-base">New design published</strong>
      </>
    ),
  },
  {
    id: "team",
    title: "Team",
    content: (
      <>
        <span className="text-xs text-muted-foreground">Project members</span>
        <strong className="block text-base">Mira, Dana and Alex</strong>
      </>
    ),
  },
];
export function SwipeTabs({
  className,
  items = defaults,
  defaultValue,
  value,
  onChange,
  label = "Project sections",
}: {
  className?: string;
  items?: SwipeTab[];
  defaultValue?: string;
  value?: string;
  onChange?: (id: string) => void;
  label?: string;
}) {
  const [selected, setSelected] = useState(defaultValue ?? items[0]?.id);
  const index = Math.max(
    0,
    items.findIndex((item) => item.id === (value ?? selected)),
  );
  const id = useId();
  const root = useRef<HTMLDivElement>(null);
  const drag = useRef<{
    pointer: number;
    start: number;
    width: number;
    started: number;
  } | null>(null);
  if (!items.length) return null;

  function activate(next: number, focus = false) {
    if (!items[next]) return;
    if (next !== index) {
      if (value === undefined) setSelected(items[next].id);
      onChange?.(items[next].id);
    }
    if (focus) document.getElementById(id + "-tab-" + next)?.focus();
  }
  function release() {
    drag.current = null;
    if (root.current) {
      delete root.current.dataset.dragging;
      root.current.style.removeProperty("--swipe-offset");
    }
  }
  return (
    <div
      ref={root}
      className={cn(
        "group/swipe w-68 max-w-full rounded-2xl border border-foreground/10 bg-card p-2 text-card-foreground shadow-sm",
        className,
      )}
      style={{ "--swipe-index": index } as CSSProperties}
    >
      <div
        role="tablist"
        aria-label={label}
        className="flex rounded-xl bg-muted p-1"
      >
        <div className="relative flex w-full">
          <span
            aria-hidden
            className="pointer-events-none absolute inset-y-0 left-0 rounded-lg bg-primary motion-safe:transition-transform motion-safe:duration-350 group-data-[dragging]/swipe:transition-none"
            style={{
              width: 100 / items.length + "%",
              transform:
                "translateX(calc((var(--swipe-index) + var(--swipe-offset, 0)) * 100%))",
            }}
          />
          {items.map((tab, i) => (
            <button
              key={tab.id}
              type="button"
              role="tab"
              id={id + "-tab-" + i}
              aria-selected={index === i}
              aria-controls={id + "-panel-" + i}
              tabIndex={index === i ? 0 : -1}
              className={
                "relative min-w-0 flex-1 truncate rounded-lg px-1.5 py-2 text-xs font-medium " +
                (index === i ? "text-primary-foreground" : "text-foreground/75")
              }
              onClick={() => activate(i)}
              onKeyDown={(e) => {
                const next = (
                  {
                    ArrowLeft: (i + items.length - 1) % items.length,
                    ArrowRight: (i + 1) % items.length,
                    Home: 0,
                    End: items.length - 1,
                  } as Record<string, number>
                )[e.key];
                if (next !== undefined) {
                  e.preventDefault();
                  activate(next, true);
                }
              }}
            >
              {tab.title}
            </button>
          ))}
        </div>
      </div>
      <div
        className="mt-2 touch-pan-y overflow-hidden rounded-xl"
        onPointerDown={(e) => {
          if (
            items.length < 2 ||
            !e.isPrimary ||
            e.button !== 0 ||
            (e.target instanceof Element &&
              e.target.closest(
                "button,input,select,textarea,a,[contenteditable=true]",
              ))
          )
            return;
          drag.current = {
            pointer: e.pointerId,
            start: e.clientX,
            width: e.currentTarget.clientWidth,
            started: e.timeStamp,
          };
          e.currentTarget.setPointerCapture(e.pointerId);
          if (root.current) root.current.dataset.dragging = "";
        }}
        onPointerMove={(e) => {
          const d = drag.current;
          if (!d || e.pointerId !== d.pointer) return;
          const shift = Math.max(
            -1,
            Math.min(1, (d.start - e.clientX) / Math.max(1, d.width)),
          );
          const offset = Math.max(
            -index,
            Math.min(items.length - 1 - index, shift),
          );
          root.current?.style.setProperty("--swipe-offset", String(offset));
        }}
        onPointerUp={(e) => {
          const d = drag.current;
          if (!d || d.pointer !== e.pointerId) return;
          const dx = d.start - e.clientX;
          release();
          if (
            Math.abs(dx) >= Math.min(56, d.width * 0.23) ||
            (Math.abs(dx) > 16 &&
              Math.abs(dx) / Math.max(1, e.timeStamp - d.started) > 0.65)
          )
            activate(index + Math.sign(dx));
        }}
        onLostPointerCapture={release}
        onPointerCancel={release}
      >
        <div
          className="flex motion-safe:transition-transform motion-safe:duration-350 group-data-[dragging]/swipe:transition-none"
          style={{
            transform:
              "translateX(calc((var(--swipe-index) + var(--swipe-offset, 0)) * -100%))",
          }}
        >
          {items.map((tab, i) => (
            <div
              key={tab.id}
              id={id + "-panel-" + i}
              role="tabpanel"
              aria-labelledby={id + "-tab-" + i}
              aria-hidden={index !== i}
              inert={index !== i}
