"use client";

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { ArrowLeft, Code2, MessageCircleQuestion, Play } from "lucide-react";
import { cn } from "@/lib/utils";
import { action, field, panel, secondary } from "@/lib/takt-surface";
import { AskTutor, type TutorAnswer } from "./ask-tutor";
import { RunConsole, type RunState } from "./run-console";
import { TestResults, type ExerciseCase } from "./test-results";

type InputCase = Omit<ExerciseCase, "actual">;
type Runner = (
  source: string,
  inputs: InputCase[],
  signal: AbortSignal,
  onRunning: () => void,
) => Promise<boolean[]>;
const cases: InputCase[] = [
  { input: "UI-7", expected: true },
  { input: "UI-X", expected: false },
  { input: "7", expected: false },
  { input: "UI-", expected: false },
  { input: "UI-42", expected: true },
];

// Patterns are data. Only this fixed worker program runs, and the caller can terminate it.
const workerProgram = `onmessage = ({data}) => {
  try {
    const pattern = new RegExp(data.source, "u");
    postMessage({ running: true });
    postMessage({ values: data.inputs.map(input => pattern.test(input)) });
  } catch (error) { postMessage({ error: error.message }); }
};`;
const runPatterns: Runner = (source, inputs, signal, onRunning) =>
  new Promise((resolve, reject) => {
    signal.throwIfAborted();
    const url = URL.createObjectURL(
      new Blob([workerProgram], { type: "text/javascript" }),
    );
    let worker: Worker;
    try {
      worker = new Worker(url);
    } finally {
      URL.revokeObjectURL(url);
    }
    function stop() {
      cleanup();
      reject(signal.reason);
    }
    function cleanup() {
      worker.terminate();
      signal.removeEventListener("abort", stop);
    }
    signal.addEventListener("abort", stop, { once: true });
    worker.onmessage = ({ data }) => {
      if (data.running) {
        onRunning();
        return;
      }
      cleanup();
      if (data.error) reject(new Error(data.error));
      else resolve(data.values);
    };
    worker.onerror = (event) => {
      cleanup();
      reject(new Error(event.message));
    };
    worker.postMessage({ source, inputs: inputs.map((item) => item.input) });
  });

function subscribeToDrafts(notify: () => void) {
  window.addEventListener("storage", notify);
  return () => window.removeEventListener("storage", notify);
}

export function CodeExercise({
  title = "Validate an ID",
  instruction = "Match UI- followed by one or more digits.",
  filename = "pattern.regex",
  initialSource = "^UI-[0-9]$",
  tests = cases,
  initialInput = "UI-42",
  onExecute = runPatterns,
  onAsk,
  draftKey,
  className,
}: {
  title?: string;
  instruction?: string;
  filename?: string;
  initialSource?: string;
  initialInput?: string;
  tests?: InputCase[];
  onExecute?: Runner;
  onAsk?: (question: string, context: string[]) => Promise<TutorAnswer>;
  draftKey?: string;
  className?: string;
}) {
  const saved = useSyncExternalStore(
    subscribeToDrafts,
    () => {
      try {
        return draftKey ? localStorage.getItem(draftKey) : null;
      } catch {
        return null;
      }
    },
    () => null,
  );
  const [edit, setEdit] = useState<{ key?: string; value: string }>();
  const source =
    edit && edit.key === draftKey ? edit.value : (saved ?? initialSource);
  const [input, setInput] = useState(initialInput);
  const [state, setState] = useState<RunState>({ phase: "idle" });
  const [results, setResults] = useState<ExerciseCase[]>([]);
  const [question, setQuestion] = useState<string[] | null>(null);
  const editor = useRef<HTMLTextAreaElement>(null);
  const [view, setView] = useState<"editor" | "output">("editor");
  const [tutorOpen, setTutorOpen] = useState(false);
  const tutorBack = useRef<HTMLButtonElement>(null);
  const outputButton = useRef<HTMLButtonElement>(null);
  const returnTo = useRef<HTMLElement | null>(null);
  const nextFocus = useRef<HTMLElement | null>(null);

  useLayoutEffect(() => {
    nextFocus.current?.focus({ preventScroll: true });
    nextFocus.current = null;
  }, [view, tutorOpen]);

  function openTutor(context: string[], trigger: HTMLButtonElement) {
    returnTo.current = trigger;
    nextFocus.current = tutorBack.current;
    setQuestion(context);
    setTutorOpen(true);
  }

  function closeTutor() {
    nextFocus.current = returnTo.current;
    setTutorOpen(false);
  }
  const active = useRef<AbortController | null>(null);
  useEffect(
    () => () => {
      if (active.current) {
        active.current.abort();
        active.current = null;
        setState({ phase: "stopped" });
      }
    },
    [],
  );
  function stop() {
    active.current?.abort();
    active.current = null;
    setState({ phase: "stopped" });
  }
  async function run(check: boolean) {
    if (active.current) return;
    const controller = new AbortController();
    active.current = controller;
    const started = performance.now();
    setResults([]);
    setQuestion(null);
    nextFocus.current = outputButton.current;
    setView("output");
    setState({ phase: "compile" });
    const batch = check ? tests : [{ input, expected: true }];
    const timer = setTimeout(() => {
      if (active.current !== controller) return;
      stop();
      setState({ phase: "error", output: "Execution timed out" });
    }, 5000);
    try {
      const values = await onExecute(source, batch, controller.signal, () => {
        if (active.current === controller) setState({ phase: "run" });
      });
      if (active.current !== controller) return;
      if (values.length !== batch.length)
        throw new Error("Incomplete response from the runner");
      const completed = batch.map((item, i) => ({
        ...item,
        actual: values[i],
      }));
      if (check) setResults(completed);
      setState({
        phase: "done",
        duration: Math.round(performance.now() - started),
        output: check ? undefined : String(values[0]),
      });
    } catch (error) {
      if (active.current === controller)
        setState({
          phase: "error",
          output: error instanceof Error ? error.message : "Run failed",
        });
    } finally {
      clearTimeout(timer);
      if (active.current === controller) active.current = null;
    }
  }
  const busy = state.phase === "run" || state.phase === "compile";
  function backToEditor() {
    nextFocus.current = editor.current;
    setView("editor");
    setTutorOpen(false);
  }
  return (
    <section
      className={cn(
        panel,
        "relative isolate w-96 max-w-full overflow-clip",
        className,
      )}
      onKeyDown={(event) => {
        if (
          tutorOpen &&
          event.key === "Escape" &&
          !event.nativeEvent.isComposing
        ) {
          event.preventDefault();
          event.stopPropagation();
          closeTutor();
        }
      }}
    >
      <div inert={tutorOpen}>
        <header>
          <strong className="text-base tracking-tight">{title}</strong>
          <p className="text-xs text-muted-foreground">{instruction}</p>
        </header>
        <div className="my-3 flex items-center justify-between border-b text-xs">
          <div role="group" aria-label="Exercise view" className="flex">
            <button
              type="button"
              aria-pressed={view === "editor"}
              onClick={() => setView("editor")}
              className="min-h-8 border-b-2 border-transparent px-2 font-medium text-muted-foreground aria-pressed:border-primary aria-pressed:text-foreground"
            >
              Editor
            </button>
            <button
              ref={outputButton}
              type="button"
              aria-pressed={view === "output"}
              disabled={state.phase === "idle"}
              onClick={() => setView("output")}
              className="min-h-8 border-b-2 border-transparent px-2 font-medium text-muted-foreground aria-pressed:border-primary aria-pressed:text-foreground disabled:opacity-45"
            >
              Result
            </button>
          </div>
          <button
            type="button"
            aria-label="Ask about this code"
            title="Ask about this code"
            disabled={busy}
            className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
            onClick={(event) => {
              const node = editor.current;
              const selected = node
                ? source.slice(node.selectionStart, node.selectionEnd)
                : "";
              openTutor(
                [filename + " · " + (selected || source), title],
                event.currentTarget,
              );
            }}
          >
            <MessageCircleQuestion size={15} />
          </button>
        </div>
        <div className="relative h-56">
          <div
            hidden={view !== "editor"}
            className="absolute inset-0 overflow-y-auto overscroll-contain"
          >
            <div className="grid gap-3 p-1">
              <label className="grid overflow-hidden rounded-xl border bg-muted/40">
                <span className="flex items-center gap-2 border-b px-3 py-1.5 font-mono text-[11px] text-muted-foreground">
                  <Code2 size={13} />
                  {filename}
                </span>
                <textarea
                  ref={editor}
                  rows={2}
                  spellCheck={false}
                  readOnly={busy}
                  value={source}
                  onChange={(e) => {
                    setEdit({ key: draftKey, value: e.target.value });
                    setState({ phase: "idle" });
                    setQuestion(null);
                    setResults([]);
                    if (draftKey)
                      try {
                        localStorage.setItem(draftKey, e.target.value);
                      } catch {
                        /* Storage is optional. */
                      }
                  }}
                  className="min-w-0 resize-y p-3 font-mono text-sm outline-offset-[-2px]"
                />
              </label>
              <label className="grid gap-1 text-xs text-muted-foreground">
                Input string
                <input
                  className={field}
                  value={input}
                  readOnly={busy}
                  onChange={(e) => {
                    setInput(e.target.value);
                    if (!results.length) setState({ phase: "idle" });
                  }}
                />
              </label>
              <div className="flex flex-wrap gap-2">
                <button
                  className={secondary}
                  type="button"
                  disabled={busy}
                  onClick={() => void run(false)}
                >
                  <Play size={13} />
                  Run
                </button>
                <button
                  className={action}
                  type="button"
                  disabled={busy || !tests.length}
                  onClick={() => void run(true)}
                >
                  Check solution
                </button>
              </div>
            </div>
          </div>
          <div
            hidden={view !== "output"}
            className="absolute inset-0 overflow-y-auto overscroll-contain p-1"
          >
            {state.phase !== "idle" && !results.length && (
              <RunConsole
                state={state}
                className="w-full border-0 p-0 shadow-none"
                onStop={stop}
                onErrorLocation={() => {
                  editor.current?.setSelectionRange(0, source.length);
                  backToEditor();
                }}
              />
            )}
            {results.length > 0 && (
              <TestResults
                results={results}
                onAsk={(row, trigger) =>
                  openTutor(
                    [
                      filename + " · " + source,
                      JSON.stringify(row.input) +
                        " → " +
                        row.actual +
                        " ≠ " +
                        row.expected,
                      title,
                    ],
                    trigger,
                  )
                }
                className="w-full border-0 p-0 shadow-none"
              />
            )}
          </div>
        </div>
      </div>
      <div
        inert={!tutorOpen}
        className={cn(
          "absolute inset-0 z-10 flex min-h-0 flex-col bg-card text-card-foreground motion-safe:transition-transform motion-safe:duration-300 motion-safe:ease-out",
          tutorOpen ? "translate-x-0" : "translate-x-full",
        )}
      >
        <div className="border-b px-3 py-2">
          <button
            ref={tutorBack}
            type="button"
            className="inline-flex min-h-8 items-center gap-1.5 rounded-lg px-2 text-xs font-medium hover:bg-muted"
            onClick={closeTutor}
          >
            <ArrowLeft size={14} />
            {view === "output" ? "Back to result" : "Back to editor"}
          </button>
        </div>
        {question && (
          <div
            key={JSON.stringify(question)}
            className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-4 py-3"
          >
            <AskTutor
              className="w-full border-0 p-0 shadow-none"
              context={question}
              onAsk={onAsk}
              onReturn={backToEditor}
            />
          </div>
        )}
      </div>
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Play, Square, Terminal } from "lucide-react";
import { cn } from "@/lib/utils";
import { secondary } from "@/lib/takt-surface";

export type RunState = {
  phase: "idle" | "compile" | "run" | "done" | "error" | "stopped";
  output?: string;
  duration?: number;
};
const labels = {
  idle: "Ready to run",
  compile: "Compiling",
  run: "Running",
  done: "Finished",
  error: "Error",
  stopped: "Stopped",
};
export function RunConsole({
  state,
  onStop,
  onErrorLocation,
  className,
}: {
  state?: RunState;
  onStop?: () => void;
  onErrorLocation?: () => void;
  className?: string;
}) {
  const [demo, setDemo] = useState<RunState>({ phase: "idle" });
  const current = state ?? demo;
  const busy = current.phase === "compile" || current.phase === "run";
  useEffect(() => {
    if (state || (demo.phase !== "compile" && demo.phase !== "run")) return;
    const started = performance.now();
    const timer = setTimeout(
      () =>
        setDemo(
          demo.phase === "compile"
            ? { phase: "run" }
            : {
                phase: "done",
                output: 'match("UI-42") → true',
                duration: Math.round(performance.now() - started),
              },
        ),
      450,
    );
    return () => clearTimeout(timer);
  }, [state, demo.phase]);
  return (
    <section
      className={cn(
        "grid w-72 max-w-full gap-3 rounded-xl border bg-card p-4 text-card-foreground shadow-sm",
        className,
      )}
    >
      <header className="flex items-center gap-2 text-xs">
        <Terminal size={16} />
        <strong className="mr-auto">Console</strong>
        {current.duration !== undefined && (
          <span className="font-mono text-muted-foreground">
            {current.duration} ms
          </span>
        )}
      </header>
      <div
        role="status"
        className="grid min-h-16 content-start gap-2 rounded-lg bg-neutral-950 p-3 font-mono text-xs text-neutral-100 dark:border dark:border-white/10"
      >
        <span
          key={current.phase}
          className="flex items-center gap-2 motion-safe:animate-in motion-safe:fade-in"
        >
          <i
            aria-hidden
            className={cn(
              "size-1.5 rounded-full bg-current",
              busy && "motion-safe:animate-pulse",
            )}
          />
          {labels[current.phase]}
        </span>
        {current.output && (
          <pre className="max-h-28 overflow-auto whitespace-pre-wrap break-all border-t pt-2">
            {current.output}
          </pre>
        )}
      </div>
      {busy && (onStop || !state) ? (
        <button
          type="button"
          className={secondary}
          onClick={onStop ?? (() => setDemo({ phase: "stopped" }))}
        >
          <Square size={12} />
          Stop
        </button>
      ) : (
        !state && (
          <button
            type="button"
            className={secondary}
            onClick={() => setDemo({ phase: "compile" })}
          >
            <Play size={13} />
            Run sample
          </button>
        )
      )}
      {current.phase === "error" && onErrorLocation && (
        <button type="button" className={secondary} onClick={onErrorLocation}>
          Go to error
        </button>
      )}
    </section>
  );
}

"use client";

import { useState } from "react";
import { Check, X, MessageCircleQuestion } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel, secondary } from "@/lib/takt-surface";

export type ExerciseCase = {
  input: string;
  expected: boolean;
  actual: boolean;
};
const sample: ExerciseCase[] = [
  { input: "UI-7", expected: true, actual: true },
  { input: "UI-42", expected: true, actual: false },
  { input: "UI-X", expected: false, actual: false },
];

export function TestResults({
  results = sample,
  onAsk,
  className,
}: {
  results?: ExerciseCase[];
  onAsk?: (result: ExerciseCase, trigger: HTMLButtonElement) => void;
  className?: string;
}) {
  const [choice, setChoice] = useState<number | null>(null);
  const failed = results.findIndex((row) => row.actual !== row.expected);
  const index =
    choice !== null && results[choice] ? choice : Math.max(0, failed);
  const row = results[index];
  return (
    <section className={cn(panel, "grid w-72 max-w-full gap-3", className)}>
      <header className="flex items-baseline justify-between gap-2">
        <strong>Tests</strong>
        <output className="font-mono text-xs tabular-nums">
          {results.filter((r) => r.expected === r.actual).length} /{" "}
          {results.length}
        </output>
      </header>
      <div className="flex flex-wrap gap-1.5">
        {results.map((test, i) => {
          const ok = test.expected === test.actual;
          const Icon = ok ? Check : X;
          return (
            <button
              key={i}
              type="button"
              aria-pressed={i === index}
              aria-label={test.input + (ok ? " · passed" : " · failed")}
              onClick={() => setChoice(i)}
              className="flex min-h-9 items-center gap-1 rounded-md border px-2 font-mono text-xs aria-pressed:border-primary aria-pressed:bg-primary/10 motion-safe:transition-colors"
            >
              <Icon size={13} />
              {String(i + 1).padStart(2, "0")}
            </button>
          );
        })}
      </div>
      {row ? (
        <div
          key={index}
          className="grid gap-2 border-t pt-2 motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-bottom-1"
        >
          <code className="break-all">{JSON.stringify(row.input)}</code>
          <dl className="grid grid-cols-2 gap-2 text-xs">
            <div>
              <dt className="text-muted-foreground">Expected</dt>
              <dd className="font-mono">{String(row.expected)}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Actual</dt>
              <dd className="font-mono">{String(row.actual)}</dd>
            </div>
          </dl>
          {onAsk && row.actual !== row.expected && (
            <button
              type="button"
              className={secondary}
              onClick={(event) => onAsk(row, event.currentTarget)}
            >
              <MessageCircleQuestion size={14} />
              Ask about this test
            </button>
          )}
        </div>
      ) : (
        <p className="text-muted-foreground">No test cases yet</p>
      )}
    </section>
  );
}

"use client";

import { useState } from "react";
import { Paperclip, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel } from "@/lib/takt-surface";
import { PromptBox } from "./prompt-box";
import { LessonCitation } from "./lesson-citation";

type Citation = Pick<
  React.ComponentProps<typeof LessonCitation>,
  "title" | "locator" | "excerpt" | "href"
>;
export type TutorAnswer = { text: string; citation?: Citation };
const defaultContext = ["lesson.md § 2.3", "pattern.regex"];
const suggestions = ["Why did this test fail?", "How does repetition work?"];
export function AskTutor({
  context = defaultContext,
  onAsk,
  onReturn,
  className,
}: {
  context?: string[];
  onAsk?: (question: string, context: string[]) => Promise<TutorAnswer>;
  onReturn?: () => void;
  className?: string;
}) {
  const [removed, setRemoved] = useState<string[]>([]);
  const [answer, setAnswer] = useState<TutorAnswer | null>(null);
  const attached = context.filter((value) => !removed.includes(value));
  async function ask(question: string) {
    setAnswer(null);
    const result = onAsk
      ? await onAsk(question, attached)
      : {
          text:
