import { cn } from "@/lib/utils";

import { ArrowUp, Check } from "lucide-react";
import { useRef, useState } from "react";
import { Button } from "@/components/ui/button";

export function ChatComposer({
  value,
  onChange,
  onSend,
  placeholder = "Write a message",
  pending = false,
  className,
}: {
  className?: string;
  pending?: boolean;
  value?: string;
  onChange?: (text: string) => void;
  onSend?: (text: string) => void | Promise<void>;
  placeholder?: string;
}) {
  const [draft, setDraft] = useState("");
  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">(
    "idle",
  );
  const sending = useRef(false);
  const input = useRef<HTMLTextAreaElement>(null);
  const text = value ?? draft;
  const busy = pending || status === "sending";
  function update(next: string) {
    if (value === undefined) setDraft(next);
    onChange?.(next);
  }
  async function submit() {
    if (!text.trim() || busy || sending.current) return;
    sending.current = true;
    setStatus("sending");
    try {
      await onSend?.(text.trim());
      update("");
      setStatus("sent");
    } catch {
      setStatus("error");
    } finally {
      sending.current = false;
    }
  }
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        void submit();
      }}
      className={cn(
        "w-full min-w-0 rounded-xl border bg-background p-2.5 text-left shadow-xs has-[textarea:focus-visible]:border-ring has-[textarea:focus-visible]:ring-2 has-[textarea:focus-visible]:ring-ring/55 forced-colors:has-[textarea:focus-visible]:outline-2",
        className,
      )}
    >
      <textarea
        ref={input}
        rows={2}
        aria-label={placeholder}
        placeholder={placeholder}
        value={text}
        readOnly={busy}
        onChange={(event) => {
          update(event.target.value);
          setStatus("idle");
        }}
        onKeyDown={(event) => {
          if (
            event.key === "Enter" &&
            !event.shiftKey &&
            !event.nativeEvent.isComposing &&
            event.nativeEvent.keyCode !== 229
          ) {
            event.preventDefault();
            if (!event.repeat) void submit();
          }
        }}
        className="block w-full resize-none bg-transparent px-1 py-0.5 text-sm text-foreground outline-none focus-visible:outline-none! placeholder:text-muted-foreground"
      />
      <div className="flex items-end justify-between gap-2">
        <span
          role="status"
          className="flex items-center gap-1 px-1 text-[11px] text-muted-foreground"
        >
          {status === "sent" ? (
            <>
              <Check size={13} />
              Sent
            </>
          ) : status === "error" ? (
            "Could not send. Try again."
          ) : busy ? (
            "Sending…"
          ) : (
            "Shift + Enter · new line"
          )}
        </span>
        <Button
          type="submit"
          size="icon"
          aria-label="Send message"
          disabled={!text.trim() || busy}
          className="rounded-full motion-safe:active:scale-90"
          onClick={() => input.current?.focus({ preventScroll: true })}
        >
          <ArrowUp />
        </Button>
      </div>
    </form>
  );
}

"use client";

import { cn } from "@/lib/utils";

import { useState } from "react";
import { SmilePlus } from "lucide-react";
import { Popover } from "radix-ui";
import { motion, useReducedMotion } from "motion/react";

export type ChatReaction = {
  emoji: string;
  label: string;
  count: number;
  mine: boolean;
};
export const studioReactions: ChatReaction[] = [
  { emoji: "👏", label: "Applause", count: 3, mine: false },
  { emoji: "❤️", label: "Like", count: 0, mine: false },
  { emoji: "💡", label: "Good idea", count: 1, mine: false },
];

export function toggleReaction(list: ChatReaction[], emoji: string) {
  return list.map((item) =>
    item.emoji === emoji
      ? {
          ...item,
          mine: !item.mine,
          count: Math.max(0, item.count + (item.mine ? -1 : 1)),
        }
      : item,
  );
}

export function MessageReactions({
  reactions,
  onToggle,
  className,
}: {
  className?: string;
  reactions?: ChatReaction[];
  onToggle?: (emoji: string) => void;
}) {
  const [local, setLocal] = useState(studioReactions);
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);
  const items = reactions ?? local;
  function toggle(emoji: string) {
    if (reactions === undefined)
      setLocal((previous) => toggleReaction(previous, emoji));
    onToggle?.(emoji);
  }
  return (
    <div
      className={cn("flex flex-wrap gap-1.5", className)}
      role="group"
      aria-label="Reactions"
    >
      {items
        .filter((item) => item.count > 0)
        .map((item) => (
          <button
            type="button"
            key={item.emoji}
            aria-label={item.label + ", " + item.count}
            aria-pressed={item.mine}
            onClick={() => toggle(item.emoji)}
            className="inline-flex min-h-7 cursor-pointer items-center gap-1.5 rounded-full border bg-card px-2 text-xs font-medium text-muted-foreground tabular-nums transition-colors hover:border-primary/40 aria-pressed:border-primary/40 aria-pressed:bg-primary/10 aria-pressed:text-primary"
          >
            <motion.span
              aria-hidden
              key={String(item.mine)}
              initial={
                item.mine && !reduce ? { scale: 0.75, rotate: -12 } : false
              }
              animate={{ scale: 1, rotate: 0 }}
              transition={{ type: "spring", stiffness: 420, damping: 15 }}
            >
              {item.emoji}
            </motion.span>
            {item.count}
          </button>
        ))}
      {items.some((item) => !item.count) && (
        <Popover.Root open={open} onOpenChange={setOpen}>
          <Popover.Trigger asChild>
            <button
              type="button"
              aria-label="Add reaction"
              className="grid size-7 place-items-center rounded-full border border-dashed text-muted-foreground hover:text-primary"
            >
              <SmilePlus size={14} />
            </button>
          </Popover.Trigger>
          <Popover.Portal>
            <Popover.Content
              side="top"
              sideOffset={5}
              collisionPadding={8}
              aria-label="Reactions"
              className="z-50 flex gap-1 rounded-xl border bg-popover p-1 text-popover-foreground shadow-md"
            >
              {items
                .filter((item) => !item.count)
                .map((item) => (
                  <button
                    type="button"
                    key={item.emoji}
                    aria-label={item.label}
                    className="grid size-8 place-items-center rounded-lg hover:bg-accent"
                    onClick={() => {
                      setOpen(false);
                      toggle(item.emoji);
                    }}
                  >
                    {item.emoji}
                  </button>
                ))}
            </Popover.Content>
          </Popover.Portal>
        </Popover.Root>
      )}
    </div>
  );
}

